/* Độc tính & an toàn. lv: doc = có độc (Dược điển ghi 有毒/小毒); manh = tác dụng mạnh, dễ hại khi quá liều/dùng lâu; luu = lưu ý an toàn cần biết */
window.TOX={
"phu-tu":{lv:"doc",lab:"CÓ ĐỘC (有毒) · NGUY HIỂM NẾU CHẾ SAI",txt:"Chứa aconitine và các alkaloid diester độc tim, độc thần kinh; củ sống hoặc bào chế sai có thể gây tử vong. Dấu hiệu ngộ độc: tê miệng lưỡi và đầu chi, buồn nôn, chóng mặt, hồi hộp, loạn nhịp tim, tụt huyết áp — đi cấp cứu ngay. Chỉ dùng loại đã bào chế, sắc trước 30–60 phút, do thầy thuốc kê. Dược điển ghi 孕妇慎用 (thận trọng); nên tránh hẳn khi mang thai. Dược điển còn ghi không dùng chung với Bán hạ, Qua lâu (cả Qua lâu tử, Qua lâu bì), Thiên hoa phấn, Bối mẫu (Xuyên, Chiết, Bình, Y lê, Hồ Bắc), Bạch liễm, Bạch cập."},
"ban-ha":{lv:"doc",lab:"CÓ ĐỘC (củ sống)",txt:"Củ sống chứa tinh thể calcium oxalate hình kim và lectin gây bỏng rát, sưng phù miệng họng, khàn tiếng, có thể gây ngạt thở do phù thanh quản. Tuyệt đối không ăn sống; chỉ dùng loại đã chế (Khương bán hạ, Pháp bán hạ…). Dược điển ghi 【注意】不宜与川乌、制川乌、草乌、制草乌、附子同用；生品内服宜慎 (không dùng chung với Xuyên ô, Chế xuyên ô, Thảo ô, Chế thảo ô, Phụ tử; củ sống uống phải thận trọng). Dược điển KHÔNG có câu 孕妇慎用 cho Bán hạ; theo y văn nên tránh khi mang thai."},
"ngai-diep":{lv:"doc",lab:"ĐỘC NHẸ (小毒)",txt:"Dược điển ghi ‘tiểu độc’. Tinh dầu chứa thujone, liều cao hoặc kéo dài có thể gây buồn nôn, nôn, chóng mặt, co giật, tổn thương gan. Không dùng quá liều, không uống nước sắc đặc kéo dài. Phụ nữ có thai không tự dùng."},
"ma-hoang":{lv:"manh",lab:"TÁC DỤNG MẠNH",txt:"Chứa ephedrine, pseudoephedrine: tăng huyết áp, tim nhanh, hồi hộp, mất ngủ, run tay; ca nặng gây đột quỵ, loạn nhịp. Không dùng cho người cao huyết áp, bệnh tim mạch, cường giáp, tăng nhãn áp, phì đại tuyến tiền liệt; không dùng giảm cân; tránh phối thuốc kích thích hoặc ức chế MAO."},
"cam-thao":{lv:"manh",lab:"HẠI KHI DÙNG LÂU / LIỀU CAO",txt:"Glycyrrhizin gây ‘giả cường aldosterone’: giữ muối nước, phù, hạ kali máu, tăng huyết áp, yếu cơ, loạn nhịp. Hay gặp khi dùng liều cao hoặc kéo dài (vài tuần). Người cao huyết áp, bệnh tim, thận, đang dùng thuốc lợi tiểu hoặc digoxin cần tránh."},
"dai-hoang":{lv:"manh",lab:"TẢ HẠ MẠNH",txt:"Anthraquinone kích thích đại tràng: đau quặn bụng, tiêu chảy, mất nước và kali nếu dùng nhiều; dùng kéo dài gây lệ thuộc nhuận tràng và nhiễm hắc tố đại tràng. Dược điển ghi 慎用 (thận trọng) với phụ nữ có thai, kỳ kinh nguyệt, cho con bú; không dùng khi tỳ vị hư hàn. Chỉ dùng ngắn ngày."},
"hoang-lien":{lv:"manh",lab:"RẤT ĐẮNG LẠNH · TRẺ SƠ SINH",txt:"Berberine có thể gây buồn nôn, tiêu chảy, đau bụng khi dùng lâu hoặc liều cao; có thể đẩy bilirubin khỏi albumin nên không dùng cho trẻ sơ sinh (nguy cơ vàng da nhân), thận trọng ở người thiếu men G6PD và phụ nữ có thai. Tương tác với thuốc chuyển hóa qua CYP (ví dụ cyclosporine)."},
"hoang-cam":{lv:"luu",lab:"LƯU Ý GAN",txt:"Có báo cáo hiếm về tổn thương gan khi dùng trong chế phẩm nhiều vị hoặc kéo dài. Ngưng và đi khám nếu vàng da, nước tiểu sẫm, mệt, đau hạ sườn phải."},
"sai-ho":{lv:"luu",lab:"LƯU Ý GAN",txt:"Liều cao hoặc dùng lâu có báo cáo hiếm về tổn thương gan (saikosaponin). Dược điển cảnh báo: Đại diệp sài hồ (Bupleurum longiradiatum) có độc, không được dùng thay Sài hồ. Người can dương thượng cang, âm hư hỏa vượng thận trọng."},
"trach-ta":{lv:"luu",lab:"LƯU Ý GAN – THẬN",txt:"Có báo cáo về độc gan, độc thận khi dùng liều cao hoặc dài ngày. Không dùng kéo dài; người suy gan, suy thận hỏi thầy thuốc."},
"nhuc-que":{lv:"luu",lab:"LƯU Ý COUMARIN",txt:"Quế cassia chứa coumarin nhiều hơn Quế Tích Lan; dùng nhiều kéo dài có thể gây tổn thương gan ở người nhạy cảm. Không dùng khi có nhiệt, chảy máu; phụ nữ có thai thận trọng."},
"bach-chi":{lv:"luu",lab:"NHẠY CẢM ÁNH SÁNG",txt:"Chứa furanocoumarin (imperatorin…) có thể gây viêm da khi phơi nắng sau khi dùng hoặc bôi. Tránh nắng gắt khi dùng liều cao."},
"hong-hoa":{lv:"luu",lab:"CHỐNG CHỈ ĐỊNH THAI KỲ · CHẢY MÁU",txt:"Hoạt huyết mạnh: có thể gây sảy thai, tăng nguy cơ chảy máu. Phụ nữ có thai thận trọng, nên tránh (Dược điển: 孕妇慎用); người dễ chảy máu, loét dạ dày, đang dùng thuốc chống đông không dùng."},
"ich-mau":{lv:"luu",lab:"CHỐNG CHỈ ĐỊNH THAI KỲ",txt:"Kích thích co bóp tử cung. Dược điển ghi 孕妇慎用; hoạt chất kích thích co bóp tử cung nên tốt nhất tránh khi mang thai; thận trọng khi rong kinh, huyết áp thấp."},
"nguu-tat":{lv:"luu",lab:"CHỐNG CHỈ ĐỊNH THAI KỲ",txt:"Hoạt huyết, dẫn huyết đi xuống, cổ thư ghi có thể gây sảy thai. Phụ nữ có thai thận trọng, nên tránh (Dược điển: 孕妇慎用); kinh nguyệt nhiều không dùng."},
"tam-that":{lv:"luu",lab:"ĐÔNG MÁU · THAI KỲ",txt:"Tác dụng hai chiều lên đông máu; người đang dùng thuốc chống đông/chống kết tập tiểu cầu hỏi thầy thuốc. Phụ nữ có thai không dùng."},
"dan-sam":{lv:"luu",lab:"TƯƠNG TÁC THUỐC CHỐNG ĐÔNG",txt:"Tương tác rõ với warfarin và thuốc chống kết tập tiểu cầu, làm tăng nguy cơ chảy máu. Người sắp phẫu thuật nên ngưng theo chỉ dẫn."},
"nhan-sam":{lv:"luu",lab:"TƯƠNG TÁC THUỐC",txt:"Có thể tương tác với warfarin, thuốc đái tháo đường, thuốc chống trầm cảm (MAO); gây mất ngủ, tăng huyết áp khi dùng liều cao. Kỵ Lê lô."},
"linh-chi":{lv:"luu",lab:"LƯU Ý CHẢY MÁU",txt:"Dùng lâu có thể gây khô miệng, rối loạn tiêu hóa, chảy máu cam; thận trọng với thuốc chống đông, thuốc hạ áp, trước phẫu thuật."},
"cat-canh":{lv:"luu",lab:"KÍCH ỨNG DẠ DÀY",txt:"Saponin kích ứng niêm mạc, liều lớn gây buồn nôn, nôn. Thận trọng khi viêm loét dạ dày, ho ra máu."},
"dong-trung-ha-thao":{lv:"luu",lab:"KIM LOẠI NẶNG · HÀNG GIẢ",txt:"Hàng hoang dã có thể nhiễm thạch tín và kim loại nặng; thị trường có nhiều hàng giả hoặc pha trộn. Mua nơi uy tín, có kiểm nghiệm."},
"quyet-minh-tu":{lv:"luu",lab:"NHUẬN TRÀNG",txt:"Anthraquinone nhuận tràng: dùng nhiều gây đau bụng, tiêu chảy; không dùng khi tiêu chảy, huyết áp thấp, có thai."},
"hau-phac":{lv:"luu",lab:"THAI KỲ",txt:"Phụ nữ có thai thận trọng; người khí hư, tân dịch thiếu không dùng."},
"thanh-hao":{lv:"luu",lab:"KHÔNG THAY THUỐC SỐT RÉT",txt:"Trà/nước sắc Thanh hao chứa rất ít artemisinin, không đủ chữa sốt rét và có thể làm chậm điều trị, tăng nguy cơ kháng thuốc. Sốt rét phải dùng phác đồ y khoa."},
"hoai-son":{lv:"luu",lab:"GÂY NGỨA KHI SỐNG",txt:"Nhựa và calcium oxalate gây ngứa tay, ngứa miệng khi xử lý/ăn sống. Đeo găng khi gọt vỏ, nấu chín trước khi ăn."},
"dam-duong-hoac":{lv:"luu",lab:"NÓNG KHÔ",txt:"Dùng quá nhiều gây khô miệng, chảy máu cam, chóng mặt; không dùng cho người âm hư hỏa vượng."},
"ha-thu-o":{lv:"manh",lab:"NGUY CƠ TỔN THƯƠNG GAN",txt:"Có nhiều báo cáo ca bệnh tổn thương gan do chế phẩm Hà thủ ô (cả sống và chế), nhất là khi dùng dài ngày, liều cao hoặc ở người mang sẵn bệnh gan. Dấu hiệu: vàng da, nước tiểu sẫm, mệt, chán ăn, đau hạ sườn phải — ngừng ngay và đi khám. Không dùng khi mang thai, có bệnh gan, nghiện rượu. Không nhầm với Hà thủ ô trắng (Streptocaulon juventas) ở Việt Nam, là loài khác."},
"ngu-tinh-thao":{lv:"luu",lab:"DẠNG TIÊM · TÍNH LẠNH",txt:"Dạng tiêm đã ghi nhận phản ứng dị ứng nặng nên bị hạn chế ở nhiều nơi; dạng uống/ăn rau ít gặp hơn. Tính hơi lạnh: người tỳ vị hư hàn, tiêu chảy ăn nhiều dễ lạnh bụng."},
"dao-nhan":{lv:"luu",lab:"THAI KỲ · AMYGDALIN",txt:"Dược điển ghi 孕妇慎用. Nhân đào chứa amygdalin, ăn sống nhiều có thể phóng thích cyanide gây ngộ độc; chỉ dùng đúng liều và dạng đã chế."},
"khuong-hoang":{lv:"luu",lab:"THAI KỲ · CHẢY MÁU",txt:"Hoạt huyết: không dùng liều thuốc khi mang thai, người dễ chảy máu hoặc đang dùng thuốc chống đông. Chế phẩm curcumin liều cao có báo cáo hiếm về tổn thương gan."},
"dien-ho-sach":{lv:"luu",lab:"BUỒN NGỦ · THAI KỲ",txt:"Alkaloid (tetrahydropalmatine) liều cao gây buồn ngủ, chóng mặt, có thể ảnh hưởng lái xe. Phụ nữ có thai không tự dùng."},
"xuyen-boi-mau":{lv:"luu",lab:"KỴ Ô ĐẦU · HÀNG GIẢ",txt:"Dược điển ghi không dùng chung với Xuyên ô, Thảo ô, Phụ tử. Thị trường nhiều hàng giả hoặc nhầm với Chiết bối mẫu; mua nơi uy tín."},
"chi-tu":{lv:"luu",lab:"RẤT LẠNH · GAN (LIỀU CAO)",txt:"Tính rất lạnh: người tỳ vị hư hàn, tiêu chảy không dùng. Geniposide liều cao gây độc gan trên động vật nên không tự tăng liều hay dùng dài ngày."},
"tay-duong-sam":{lv:"luu",lab:"KỴ LÊ LÔ · TƯƠNG TÁC THUỐC",txt:"Dược điển ghi không dùng chung với Lê lô. Có thể tương tác với thuốc chống đông, thuốc đái tháo đường."},
"dang-sam":{lv:"luu",lab:"KỴ LÊ LÔ",txt:"Dược điển ghi không dùng chung với Lê lô. Người thực nhiệt, đầy bụng khí trệ thận trọng."},
"hanh-nhan":{lv:"doc",lab:"CÓ ĐỘC NHẸ (小毒)",txt:"Dược điển ghi ‘có độc nhẹ’ và ‘không dùng quá liều’. Nhân đắng chứa amygdalin, khi thủy phân giải phóng hydro cyanide; ăn sống nhiều (nhất là trẻ em) có thể gây ngộ độc nặng. Chỉ dùng loại đã chế, đúng liều. Không nhầm với hạnh nhân ngọt ăn được."},
"ngo-thu-du":{lv:"doc",lab:"CÓ ĐỘC NHẸ (小毒)",txt:"Dược điển ghi ‘có độc nhẹ’. Liều cao hoặc dùng dài ngày gây buồn nôn, đau đầu, ảo giác, kích ứng. Âm hư có nhiệt không dùng; phụ nữ có thai thận trọng."},
"bo-cot-chi":{lv:"manh",lab:"NHẠY SÁNG · NGUY CƠ GAN",txt:"Furanocoumarin (psoralen) gây nhạy cảm ánh sáng: viêm da, sạm da khi phơi nắng. Dược điển không ghi cảnh báo, nhưng có nhiều báo cáo ca bệnh tổn thương gan do chế phẩm Bổ cốt chi. Người bệnh gan, đang dùng thuốc độc gan không dùng; tránh nắng khi dùng; theo dõi chức năng gan nếu dùng kéo dài."},
"phong-ky":{lv:"manh",lab:"DỄ NHẦM VỚI LOÀI ĐỘC THẬN",txt:"‘Phòng kỷ’ thật là Stephania tetrandra. Quảng phòng kỷ, Mộc phòng kỷ (Aristolochia) chứa aristolochic acid gây suy thận mạn và ung thư đường tiết niệu; từng gây ‘bệnh thận do thuốc giảm cân’ ở Bỉ khi bị dùng nhầm. Chỉ mua hàng có xác định loài; phụ nữ có thai không dùng."},
"mau-don-bi":{lv:"luu",lab:"THAI KỲ",txt:"Dược điển ghi 孕妇慎用; kinh nguyệt nhiều, tỳ vị hư hàn không dùng."},
"huyen-sam":{lv:"luu",lab:"KỴ LÊ LÔ",txt:"Dược điển ghi không dùng chung với Lê lô. Tỳ vị hư hàn, tiêu chảy không dùng."},
"hoang-ba":{lv:"luu",lab:"RẤT ĐẮNG LẠNH",txt:"Dễ hại vị: tỳ vị hư hàn, tiêu chảy lạnh không dùng; thai kỳ thận trọng. Berberine có thể tương tác thuốc chuyển hóa qua CYP."},
"long-dom":{lv:"luu",lab:"RẤT ĐẮNG LẠNH",txt:"Không dùng dài ngày; tỳ vị hư hàn, tiêu chảy không dùng; thai kỳ thận trọng."},
"moc-huong":{lv:"luu",lab:"CITES · DỄ NHẦM THANH MỘC HƯƠNG",txt:"Saussurea costus hoang dã thuộc Phụ lục I CITES (hạn chế buôn bán). ‘Thanh mộc hương’ (Aristolochia) chứa aristolochic acid độc thận, gây ung thư — tuyệt đối không dùng thay Mộc hương."},
"hoa-ma-nhan":{lv:"luu",lab:"PHÁP LÝ · ĂN NHIỀU",txt:"Cây Cannabis bị quản lý nghiêm tại Việt Nam; chỉ dùng hạt hợp pháp đã xử lý. Ăn nhiều gây tiêu chảy, buồn nôn, đau đầu; phụ nữ có thai thận trọng."},
"can-khuong":{lv:"luu",lab:"RẤT CAY NÓNG",txt:"Âm hư nội nhiệt, thực nhiệt, ho ra máu do nhiệt không dùng; phụ nữ có thai thận trọng."},
"xuyen-o":{lv:"doc",lab:"ĐỘC MẠNH (大毒)",txt:"Rễ mẹ của cây Ô đầu: chứa aconitine độc tim, độc thần kinh cực mạnh, vài miligam có thể gây tử vong. Tuyệt đối không dùng sống, không ngâm rượu uống. Chỉ dùng loại đã chế do thầy thuốc kê, sắc trước và lâu. Dược điển: củ sống 孕妇禁用, củ chế 孕妇慎用; nên tránh hẳn khi mang thai; kỵ Bán hạ, Qua lâu (cả Qua lâu tử, Qua lâu bì), Thiên hoa phấn, Bối mẫu (Xuyên, Chiết, Bình, Y lê, Hồ Bắc), Bạch liễm, Bạch cập. Ngộ độc: tê môi lưỡi, buồn nôn, loạn nhịp tim — cấp cứu ngay."},
"thien-nam-tinh":{lv:"doc",lab:"CÓ ĐỘC (củ sống)",txt:"Củ sống chứa tinh thể calcium oxalate và chất kích ứng, gây tê rát, sưng phù miệng họng, có thể ngạt thở. Chỉ dùng loại đã chế. Không nhầm với các cây họ Ráy ăn được; phụ nữ có thai thận trọng."},
"ma-tien-tu":{lv:"doc",lab:"ĐỘC MẠNH (大毒)",txt:"Chứa strychnine gây co giật toàn thân, tử vong do liệt cơ hô hấp; liều gây chết chỉ khoảng vài chục miligam. Chỉ dùng loại đã chế, liều rất nhỏ, vào hoàn tán, do thầy thuốc kê. Không sắc uống. Dược điển: 孕妇禁用; vận động viên thận trọng; không bôi diện rộng vì độc tố ngấm qua da."},
"bach-qua":{lv:"doc",lab:"CÓ ĐỘC (hạt sống)",txt:"Nhân hạt chứa ginkgotoxin gây co giật, hôn mê, nhất là ở trẻ em ăn nhiều (trên khoảng 10 hạt); lớp thịt ngoài gây dị ứng da. Không ăn sống, không ăn nhiều, nấu chín kỹ."},
"khoan-dong-hoa":{lv:"luu",lab:"ALKALOID PYRROLIZIDINE · GAN",txt:"Chứa pyrrolizidine alkaloid có thể độc gan, gây đột biến. Không dùng dài ngày hoặc liều cao; người bệnh gan, phụ nữ có thai và cho con bú không dùng."},
"nhuc-dau-khau":{lv:"luu",lab:"QUÁ LIỀU GÂY ẢO GIÁC",txt:"Myristicin ở liều cao (vài gram sống) gây buồn nôn, ảo giác, nhịp tim nhanh; dùng thuốc phải chế (nướng) và đúng liều, không dùng như chất kích thích."},
"dinh-huong":{lv:"luu",lab:"KỴ UẤT KIM · DẦU NGUYÊN CHẤT",txt:"Dược điển ghi không dùng chung với Uất kim. Dầu đinh hương nguyên chất gây bỏng niêm mạc, độc với trẻ em; không nuốt nguyên chất."},
"uat-kim":{lv:"luu",lab:"KỴ ĐINH HƯƠNG",txt:"Dược điển ghi không dùng chung với Đinh hương, Mẫu đinh hương. Phụ nữ có thai thận trọng."},
"bach-cap":{lv:"luu",lab:"KỴ Ô ĐẦU",txt:"Không dùng chung với Xuyên ô, Thảo ô, Phụ tử (‘phản ô đầu’)."},
"chi-thuc":{lv:"luu",lab:"THAI KỲ · SYNEPHRINE",txt:"Dược điển ghi 孕妇慎用. Chứa synephrine có thể làm nhịp tim, huyết áp tăng nhẹ ở người nhạy cảm."},
"dia-du":{lv:"luu",lab:"KHÔNG BÔI DIỆN BỎNG RỘNG",txt:"Theo y văn hiện đại (Dược điển không có dòng này): tannin hấp thu qua diện bỏng rộng có thể gây độc gan; không bôi chế phẩm Địa du lên vết bỏng lớn. Tỳ vị hư hàn, tiêu chảy lạnh không dùng."},
"bach-mao-can":{lv:"luu",lab:"NHIỀU KALI",txt:"Hàm lượng kali cao: người suy thận, đang dùng thuốc giữ kali thận trọng. Tính lạnh, tỳ vị hư hàn không dùng."},
"vien-chi":{lv:"luu",lab:"KÍCH ỨNG DẠ DÀY",txt:"Saponin gây kích ứng niêm mạc, buồn nôn: người loét dạ dày, viêm dạ dày thận trọng; thường chế Cam thảo để giảm kích ứng."},
"phan-ta-diep":{lv:"manh",lab:"TẢ HẠ · DÙNG NGẮN NGÀY",txt:"Sennoside kích thích đại tràng: dùng dài ngày gây lệ thuộc nhuận tràng, mất kali, rối loạn điện giải. Dược điển ghi 孕妇慎用 (thận trọng khi có thai); không dùng cho phụ nữ cho con bú, trẻ em, người tắc ruột, đau bụng chưa rõ nguyên nhân; không dùng để giảm cân."},
"xuyen-tam-lien":{lv:"luu",lab:"RẤT ĐẮNG LẠNH · DẠNG TIÊM",txt:"Hại vị nếu dùng nhiều hoặc dài ngày; tỳ vị hư hàn không dùng; thai kỳ thận trọng; dạng tiêm từng ghi nhận phản ứng dị ứng nặng."},
"bach-hoa-xa-thiet-thao":{lv:"luu",lab:"KHÔNG THAY ĐIỀU TRỊ UNG THƯ",txt:"Nhiều nơi truyền miệng ‘chữa ung thư’ nhưng chưa có chứng cứ lâm sàng mạnh. Không dùng thay điều trị y khoa; tính lạnh, tỳ vị hư hàn và phụ nữ có thai thận trọng."},
"xich-thuoc":{lv:"luu",lab:"KỴ LÊ LÔ",txt:"Không dùng chung với Lê lô. Huyết hư không có ứ, thai kỳ thận trọng."},
"chiet-boi-mau":{lv:"luu",lab:"KỴ Ô ĐẦU",txt:"Dược điển ghi không dùng chung nhóm Ô đầu, Phụ tử. Ho do lạnh, tỳ vị hư hàn không dùng."},
"tang-ky-sinh":{lv:"luu",lab:"CÂY CHỦ CÓ ĐỘC",txt:"Tầm gửi mọc trên cây có độc có thể mang độc; chỉ dùng loại có nguồn gốc, cây chủ rõ ràng (như dâu)."},
"tieu-hoi-huong":{lv:"luu",lab:"DẠNG TINH DẦU · KHÔNG NHẦM ĐẠI HỒI",txt:"Estragole ở liều cao kéo dài có nguy cơ trên động vật; hạn chế tinh dầu liều cao. Không nhầm với Đại hồi; Illicium anisatum (Mãng thảo) có độc, từng bị trộn lẫn."},
"bach-bo":{lv:"luu",lab:"QUÁ LIỀU GÂY BUỒN NÔN",txt:"Alkaloid Stemona liều cao hoặc dài ngày gây buồn nôn, chóng mặt, kích ứng dạ dày; tỳ vị hư yếu, thai kỳ thận trọng."},
"cao-luong-khuong":{lv:"luu",lab:"TƯƠNG TÁC THUỐC",txt:"Galangin ức chế men chuyển hóa thuốc (CYP); người dùng nhiều thuốc cần hỏi thầy thuốc. Âm hư hỏa vượng không dùng."},
"tru-linh":{lv:"luu",lab:"LỢI TIỂU MẠNH",txt:"Dùng dài ngày dễ mất tân dịch; âm hư không có thấp không dùng."},
"thuong-nhi-tu":{lv:"doc",lab:"CÓ ĐỘC",txt:"Chứa carboxyatractyloside độc gan, thận, tim; quá liều hoặc dùng sống gây buồn nôn, đau bụng, tổn thương gan nặng, suy thận, có thể tử vong, nhất là trẻ em. Chỉ dùng loại đã sao, đúng liều, theo thầy thuốc; trẻ em, phụ nữ có thai, người bệnh gan thận không dùng."},
"son-dau-can":{lv:"doc",lab:"CÓ ĐỘC",txt:"Alkaloid (matrine, oxymatrine) liều cao gây buồn nôn, chóng mặt, run, tê, khó thở. Không dùng quá liều hay dài ngày; trẻ em, phụ nữ có thai không dùng. Không nhầm với Bắc đậu căn (Menispermum)."},
"xuyen-luyen-tu":{lv:"doc",lab:"CÓ ĐỘC NHẸ (小毒)",txt:"Dược điển ghi ‘có độc nhẹ’. Toosendanin độc gan và thần kinh; không dùng quá liều hoặc dài ngày; người bệnh gan, thận, phụ nữ có thai, tỳ vị hư hàn không dùng."},
"tan-lang":{lv:"manh",lab:"ARECOLINE · NGUY CƠ UNG THƯ",txt:"Nhai hạt cau/trầu cau lâu dài làm tăng nguy cơ ung thư khoang miệng, xơ hóa dưới niêm mạc (IARC nhóm 1) và gây nghiện nhẹ. Liều thuốc đúng chỉ định; liều diệt sán (30–60 g) chỉ dùng theo thầy thuốc; người hen, nhịp tim chậm, phụ nữ có thai thận trọng."},
"nga-truat":{lv:"luu",lab:"CẤM KHI CÓ THAI",txt:"Dược điển ghi 孕妇禁用 (cấm khi có thai). Phá huyết mạnh: người rong kinh, dễ chảy máu, huyết hư không dùng."},
"thien-hoa-phan":{lv:"luu",lab:"THAI KỲ · KỴ Ô ĐẦU",txt:"Dược điển ghi 孕妇慎用; kỵ Xuyên ô, Phụ tử, Thảo ô. Trichosanthin có thể gây sảy thai, dị ứng nặng. Phụ nữ có thai thận trọng, nên tránh; tỳ vị hư hàn, tiêu chảy không dùng."},
"thang-ma":{lv:"luu",lab:"LIỀU CAO",txt:"Liều cao gây buồn nôn, chóng mặt, đau đầu; âm hư hỏa vượng, hồi hộp, hen suyễn không dùng. Không nhầm với black cohosh (Cimicifuga racemosa) có báo cáo độc gan."},
"trung-lau":{lv:"doc",lab:"CÓ ĐỘC NHẸ (小毒)",txt:"Saponin steroid (polyphyllin) gây buồn nôn, nôn, tiêu chảy, chóng mặt khi quá liều. Không dùng quá liều hoặc dài ngày; phụ nữ có thai, người tỳ vị hư hàn không dùng. Rắn cắn phải đi cấp cứu, không tự điều trị bằng thảo dược."},
"bach-tien-bi":{lv:"manh",lab:"CÓ BÁO CÁO TỔN THƯƠNG GAN",txt:"Dictamnine độc gan trên thực nghiệm; có báo cáo tổn thương gan ở người dùng liều cao. Người bệnh gan, đang dùng thuốc độc gan, phụ nữ có thai không dùng; dùng ngắn ngày."},
"kho-sam":{lv:"luu",lab:"KỴ LÊ LÔ · RẤT ĐẮNG LẠNH",txt:"Không dùng chung với Lê lô. Matrine liều cao gây buồn nôn, chóng mặt, run; tỳ vị hư hàn không dùng. Không nhầm với ‘khổ sâm Bắc Bộ’ (Croton tonkinensis) ở Việt Nam."},
"bach-dau-ong":{lv:"luu",lab:"CÂY TƯƠI KÍCH ỨNG DA",txt:"Cây tươi chứa anemonin gây phồng rộp da, kích ứng niêm mạc; không giã đắp lâu. Rất đắng lạnh: tỳ vị hư hàn, tiêu chảy không do nhiệt không dùng."},
"ngu-gia-bi":{lv:"luu",lab:"KHÔNG NHẦM HƯƠNG GIA BÌ",txt:"‘Bắc ngũ gia bì’ (Hương gia bì, Periploca sepium) có độc tim (cardiac glycoside), khác hẳn Ngũ gia bì (Eleutherococcus). Chỉ mua loại có xác định tên khoa học."},
"xich-tieu-dau":{lv:"luu",lab:"KHÔNG NHẦM TƯƠNG TƯ TỬ",txt:"Xích tiểu đậu (Vigna) ăn được, khác hạt cườm đỏ có chấm đen Tương tư tử (Abrus precatorius) chứa abrin cực độc, có thể gây tử vong dù chỉ nhai vài hạt."},
"thach-xuong-bo":{lv:"luu",lab:"β-ASARONE · KHÔNG NHẦM THỦY XƯƠNG BỒ",txt:"β-asarone có nguy cơ gây ung thư trên chuột liều cao kéo dài; không dùng liều cao hay dài ngày. Không nhầm với Thủy xương bồ (Acorus calamus) chứa nhiều β-asarone hơn."},
"ma-tien-thao":{lv:"luu",lab:"THAI KỲ",txt:"Phụ nữ có thai thận trọng; tỳ vị hư hàn, tiêu chảy không dùng; liều cao gây buồn nôn."},
"vuong-bat-luu-hanh":{lv:"luu",lab:"THAI KỲ",txt:"Kích thích co tử cung nhẹ: phụ nữ có thai thận trọng; người huyết hư, rong kinh không dùng."},
"thao-o":{lv:"doc",lab:"ĐỘC MẠNH (大毒)",txt:"Chứa aconitine độc tim, độc thần kinh cực mạnh, vài miligam có thể gây tử vong. Tuyệt đối không dùng sống, không ngâm rượu uống. Chỉ dùng loại đã chế do thầy thuốc kê, sắc trước và lâu. Cấm khi có thai; kỵ Bán hạ, Qua lâu, Bối mẫu, Bạch liễm, Bạch cập, Thiên hoa phấn. Ngộ độc: tê môi lưỡi, buồn nôn, loạn nhịp tim — cấp cứu ngay."},
"duong-kim-hoa":{lv:"doc",lab:"CÓ ĐỘC",txt:"Alkaloid tropane (scopolamine, hyoscyamine, atropine) gây khô miệng, giãn đồng tử, tim nhanh, lú lẫn, ảo giác, sốt, có thể hôn mê và ngưng thở. Chỉ do thầy thuốc kê, liều rất hẹp, vào hoàn tán; cấm khi có thai, glôcôm, cao huyết áp, tim nhanh; không tự dùng làm thuốc hút (Dược điển có dạng cuốn hút ≤1,5 g/ngày nhưng chỉ do thầy thuốc chỉ định); để xa tầm tay trẻ em."},
"thanh-tuong-tu":{lv:"luu",lab:"GIÃN ĐỒNG TỬ · GLÔCÔM",txt:"Hạt có tác dụng giãn đồng tử: người bị glôcôm (tăng nhãn áp) không dùng. Tỳ vị hư hàn không dùng nhiều; phụ nữ có thai thận trọng."},
"tram-huong":{lv:"luu",lab:"CITES · HÀNG GIẢ",txt:"Các loài Aquilaria thuộc Phụ lục II CITES: chỉ dùng nguồn hợp pháp. Nhiều hàng giả (gỗ tẩm hóa chất). Âm hư hỏa vượng không dùng."},
"dan-huong":{lv:"luu",lab:"HÀNG GIẢ · ÂM HƯ",txt:"Nhiều hàng giả (gỗ tẩm tinh dầu). Âm hư hỏa vượng, đang chảy máu cam hoặc ho ra máu không dùng."},
"moc-tac":{lv:"luu",lab:"THIẾU VITAMIN B1 NẾU DÙNG DÀI",txt:"Chứa thiaminase: dùng liều cao kéo dài có thể gây thiếu vitamin B1. Dùng ngắn ngày, đúng liều."},
"bo-hoang":{lv:"luu",lab:"BỌC VẢI · THAI KỲ",txt:"Phải bọc vải khi sắc; sống kích thích co tử cung nên phụ nữ có thai thận trọng; sao than dùng cầm máu."},
"le-chi-hach":{lv:"luu",lab:"HẠ ĐƯỜNG HUYẾT Ở TRẺ",txt:"Hạt vải chứa chất tương tự hypoglycin: không để trẻ nhỏ ăn hạt hoặc ăn nhiều vải lúc đói (nguy cơ hạ đường huyết, bệnh não cấp)."},
"ho-lo-ba":{lv:"luu",lab:"THAI KỲ · THUỐC ĐÁI THÁO ĐƯỜNG",txt:"Phụ nữ có thai không dùng liều thuốc; có thể hạ đường huyết, tương tác với thuốc đái tháo đường, chống đông; có thể gây tiêu chảy, đầy hơi."},
"hong-canh-thien":{lv:"luu",lab:"MẤT NGỦ · RỐI LOẠN LƯỠNG CỰC",txt:"Có thể gây mất ngủ, hồi hộp nếu dùng buổi tối hoặc liều cao; người rối loạn lưỡng cực, đang dùng thuốc chống trầm cảm hoặc ức chế miễn dịch cần hỏi thầy thuốc."},
"ho-tieu":{lv:"luu",lab:"PIPERINE · TƯƠNG TÁC THUỐC",txt:"Piperine làm thay đổi chuyển hóa nhiều thuốc (phenytoin, propranolol, theophylline…). Ăn nhiều gây kích ứng dạ dày; trĩ chảy máu, viêm loét dạ dày không dùng nhiều."},
"dai-hoi":{lv:"luu",lab:"KHÔNG NHẦM MÃNG THẢO",txt:"Illicium anisatum (Mãng thảo, Nhật) chứa anisatin độc thần kinh, từng bị trộn vào Đại hồi gây ngộ độc. Chỉ mua loại có xác định loài; Đại hồi thật có 8 cánh (thường 7–9)."},
"tat-le":{lv:"doc",lab:"CÓ ĐỘC NHẸ (小毒)",txt:"Dược điển ghi ‘có độc nhẹ’. Không dùng quá liều; thận trọng khi dùng chế phẩm ‘tăng testosterone’ liều cao vì có báo cáo ngộ độc; phụ nữ có thai thận trọng."},
"bach-gioi-tu":{lv:"luu",lab:"KÍCH ỨNG DA KHI ĐẮP",txt:"Isothiocyanate cay nồng gây phồng rộp nếu đắp lâu; da nhạy cảm, mụn nhọt đã vỡ không đắp; phế nhiệt ho không dùng."},
"hai-tao":{lv:"luu",lab:"KỴ CAM THẢO · IOD · ARSENIC",txt:"Dược điển ghi không dùng chung với Cam thảo. Nhiều iod: người cường giáp, bệnh tuyến giáp tự miễn không dùng nhiều; hijiki (Sargassum fusiforme) có thể chứa arsenic vô cơ cao."},
"qua-lau":{lv:"luu",lab:"KỴ Ô ĐẦU",txt:"Dược điển ghi không dùng chung nhóm Ô đầu, Phụ tử, Thảo ô. Tính hàn: tỳ vị hư hàn, đại tiện lỏng không dùng."},
"bach-liem":{lv:"luu",lab:"KỴ Ô ĐẦU",txt:"Dược điển ghi không dùng chung với Xuyên ô, Thảo ô, Phụ tử."},
"moc-thong":{lv:"manh",lab:"KHÔNG NHẦM QUAN MỘC THÔNG",txt:"Quan mộc thông, Quảng phòng kỷ, Thanh mộc hương (Aristolochia) chứa aristolochic acid gây suy thận, ung thư; đã bị loại khỏi Dược điển. Chỉ mua loại Akebia có xác định loài; phụ nữ có thai không dùng."},
"nhu-huong":{lv:"luu",lab:"THAI KỲ · DẠ DÀY YẾU",txt:"Dược điển ghi: phụ nữ có thai và người vị yếu thận trọng. Dễ gây buồn nôn, kích ứng dạ dày."},
"to-moc":{lv:"luu",lab:"THAI KỲ",txt:"Dược điển ghi 孕妇慎用 (thận trọng khi có thai)."},
"ban-bien-lien":{lv:"luu",lab:"LOBELINE · RẮN CẮN",txt:"Lobeline liều cao gây buồn nôn, nôn. Rắn cắn phải đi cấp cứu, không tự điều trị bằng thảo dược; phụ nữ có thai thận trọng."},
"ban-chi-lien":{lv:"luu",lab:"KHÔNG THAY ĐIỀU TRỊ UNG THƯ",txt:"Thường dùng bổ trợ ung thư trong Đông y nhưng chưa có chứng cứ lâm sàng mạnh; không thay điều trị y khoa. Tính lạnh: tỳ vị hư hàn, phụ nữ có thai thận trọng."},
"khien-nguu-tu":{"lv": "doc", "lab": "CÓ ĐỘC · CẤM KHI CÓ THAI", "txt": "Dược điển ghi 有毒 (có độc). Xổ mạnh, liều cao gây đau bụng, nôn, tổn thương thận. Phụ nữ có thai CẤM dùng; không dùng chung với Ba đậu, Ba đậu sương."},
"ba-dau":{"lv": "doc", "lab": "ĐỘC MẠNH · CẤM KHI CÓ THAI", "txt": "Dược điển ghi 有大毒 (độc mạnh). Dầu ba đậu gây phồng rộp da, kích ứng niêm mạc, xổ dữ dội; chỉ dùng ngoài hoặc dạng Ba đậu sương theo chỉ định. Phụ nữ có thai CẤM dùng; không dùng chung với Khiên ngưu tử."},
"kinh-dai-kich":{"lv": "doc", "lab": "CÓ ĐỘC · KỴ CAM THẢO", "txt": "Dược điển ghi 有毒 (có độc). Xổ nước mạnh, nhựa mủ kích ứng da mắt. Phụ nữ có thai CẤM dùng; không dùng chung với Cam thảo; chỉ dùng loại đã chế giấm khi uống."},
"nguyen-hoa":{"lv": "doc", "lab": "CÓ ĐỘC · CẤM KHI CÓ THAI", "txt": "Theo giáo trình: có độc, xổ nước mạnh, kích ứng tiêu hóa; phụ nữ có thai cấm dùng, không dùng chung với Cam thảo. Chưa đối chiếu được với Dược điển."},
"thuong-luc":{"lv": "doc", "lab": "CÓ ĐỘC · DỄ NHẦM NHÂN SÂM", "txt": "Dược điển ghi 有毒 (có độc). Quá liều gây nôn, tiêu chảy, mê sảng, co giật; rễ từng bị nhầm với Nhân sâm gây ngộ độc. Quả cũng độc. Phụ nữ có thai CẤM dùng."},
"thien-kim-tu":{"lv": "doc", "lab": "CÓ ĐỘC · CẤM KHI CÓ THAI", "txt": "Dược điển ghi 有毒 (có độc) và ‘phụ nữ có thai cấm dùng, để tránh ngộ độc’. Xổ mạnh, nhựa kích ứng mắt da; dùng dạng đã bỏ vỏ ép bớt dầu."},
"lo-hoi":{"lv": "luu", "lab": "THAI KỲ · XỔ", "txt": "Dược điển ghi: phụ nữ có thai thận trọng. Nhựa lô hội xổ mạnh, khác với gel làm mỹ phẩm; không dùng khi xuất huyết trực tràng, tiêu chảy do hư hàn."},
"uc-ly-nhan":{"lv": "luu", "lab": "THAI KỲ", "txt": "Dược điển ghi: phụ nữ có thai thận trọng. Nhân hạt chứa amygdalin, không dùng liều cao kéo dài."},
"bach-phu-tu":{"lv": "doc", "lab": "CÓ ĐỘC · KHÔNG UỐNG SỐNG", "txt": "Dược điển ghi 有毒 (có độc). Phụ nữ có thai thận trọng; củ sống uống phải thận trọng, chỉ dùng loại đã chế. Không nhầm với ‘Quan bạch phụ’ (Aconitum coreanum, loài khác)."},
"thuong-son":{"lv": "doc", "lab": "CÓ ĐỘC · GÂY NÔN", "txt": "Dược điển ghi 有毒 (có độc), gây nôn, không dùng liều lớn; phụ nữ có thai thận trọng. Người tỳ vị yếu không dùng."},
"thau-dau":{"lv": "doc", "lab": "HẠT RẤT ĐỘC · RICIN", "txt": "Dược điển ghi 有毒 (có độc). Hạt chứa ricin, vài hạt nhai nát có thể gây tử vong; trẻ em tuyệt đối tránh ăn nhầm. Chỉ dùng ngoài hoặc theo chỉ định."},
"kho-luyen-bi":{"lv": "doc", "lab": "CÓ ĐỘC · GAN THẬN", "txt": "Dược điển ghi 有毒 (có độc): phụ nữ có thai và người chức năng gan thận kém thận trọng. Không dùng quá liều hoặc kéo dài."},
"quan-chung":{"lv": "doc", "lab": "TIỂU ĐỘC", "txt": "Chuyên luận Miên mã quán chúng trong Dược điển ghi 有小毒 (có độc nhẹ). Theo y văn: phụ nữ có thai không dùng; dùng liều cao gây tổn hại thị giác, gan thận."},
"le-lo":{"lv": "doc", "lab": "ĐỘC MẠNH · THẬP BÁT PHẢN", "txt": "Độc mạnh với tim và thần kinh (alkaloid steroid), gây nôn dữ dội, hạ huyết áp, chậm nhịp tim. Không dùng chung với Nhân sâm, Sa sâm, Đan sâm, Huyền sâm, Khổ sâm, Tế tân, Thược dược; phụ nữ có thai cấm dùng. Chưa đối chiếu được với Dược điển."},
"su-quan-tu":{"lv": "luu", "lab": "KIÊNG TRÀ ĐẶC · TRẺ EM", "txt": "Dược điển ghi: khi dùng thuốc kiêng uống trà đặc; trẻ em mỗi tuổi 1–1,5 hạt, tối đa 20 hạt/ngày. Quá liều gây nấc cụt, nôn, chóng mặt."},
"huong-nhu":{"lv": "luu", "lab": "CHỈ DÙNG KHI CÓ BIỂU HÀN", "txt": "Hương nhu cay ấm, phát hãn khá mạnh: người đang ra nhiều mồ hôi (biểu hư) hoặc cảm nắng thể nhiệt không có biểu hàn thì không dùng. Ở Việt Nam, ‘Hương nhu trắng/tía’ là các loài Ocimum (é) chứ không phải vị Hương nhu Trung Quốc (Mosla chinensis); đừng thay lẫn."},
"phu-binh":{"lv": "luu", "lab": "BIỂU HƯ, NGUỒN BẨN", "txt": "Theo giáo trình, người tự ra mồ hôi (biểu hư) không dùng. Bèo vớt ở ao tù dễ nhiễm bẩn, cần rửa kỹ. Không nhầm với Bèo cái (Pistia stratiotes) hay Thanh bình (Lemna minor)."},
"dai-thanh-diep":{"lv": "luu", "lab": "DỄ NHẦM LOÀI", "txt": "Tên ‘đại thanh diệp’ từng dùng lẫn cho lá Mã lam (chàm mèo), Liêu lam và Đại thanh (Clerodendrum cyrtophyllum); Dược điển 2020 chỉ nhận lá Isatis indigotica. Tính rất lạnh: tỳ vị hư hàn, tiêu chảy thận trọng, không dùng kéo dài."},
"dai-huyet-dang":{"lv": "luu", "lab": "THẬN TRỌNG KHI CÓ THAI", "txt": "Theo giáo trình, vị này hoạt huyết nên phụ nữ có thai thận trọng. Không nhầm với Kê huyết đằng (Spatholobus suberectus) hay các ‘huyết đằng’ khác cũng có nhựa đỏ – khác họ, khác công năng."},
"bai-tuong":{"lv": "luu", "lab": "HÀNG LẪN LOÀI", "txt": "Nhiều vùng bán lẫn Khổ mãi thái (Sonchus brachyotus), Tích minh (Thlaspi arvense) dưới tên ‘Bại tương thảo’ – khác loài, khác tính vị. Theo giáo trình, tỳ vị hư hàn, tiêu chảy do hàn không dùng."},
"ma-bot":{"lv": "luu", "lab": "BÀO TỬ KÍCH ỨNG, NHẦM NẤM ĐỘC", "txt": "Bào tử khô rất mịn, hít vào có thể kích ứng đường hô hấp; khi sắc nên bọc vải. Không tự hái nấm hình cầu mọc hoang để dùng vì dễ nhầm với nấm cầu độc (Scleroderma) hoặc trứng nấm độc (Amanita)."},
"nha-dam-tu":{"lv": "doc", "lab": "CÓ ĐỘC NHẸ", "txt": "Dược điển ghi ‘có độc nhẹ’ (小毒). Nhân hạt rất đắng, kích ứng niêm mạc tiêu hóa gây buồn nôn, nôn, đau bụng, tiêu chảy; quá liều có báo cáo tổn thương gan, thận. Chỉ dùng liều nhỏ (0,5–2 g), bọc trong cùi nhãn hoặc đóng nang, không nhai; thận trọng ở trẻ em, người bệnh gan thận, dạ dày – ruột và phụ nữ có thai. Dùng ngoài có tính ăn mòn, tránh để dính da lành."},
"dia-cam-thao":{"lv": "luu", "lab": "NHỰA MỦ KÍCH ỨNG", "txt": "Cây có nhựa trắng như sữa, có thể gây kích ứng da, mắt khi dùng tươi; tránh để dính mắt. Dễ nhầm với các loài cỏ sữa khác (Euphorbia thymifolia, E. hirta) – công dụng dân gian gần giống nhưng không phải Địa cẩm thảo của Dược điển."},
"son-tu-co":{"lv": "luu", "lab": "NHẦM VỚI CÂY CHỨA COLCHICINE", "txt": "Tên ‘Sơn từ cô’ từng bị dùng nhầm cho ‘Quang từ cô’ (Iphigenia indica) và các cây chứa colchicine, có thể gây ngộ độc nặng (buồn nôn, tiêu chảy dữ dội, suy đa cơ quan). Dược điển 2020 chỉ nhận ba loài lan Cremastra appendiculata, Pleione bulbocodioides, P. yunnanensis; không tự đào cây hoang. Người thể nhược và phụ nữ có thai thận trọng."},
"thien-ly-quang":{"lv": "manh", "lab": "ALKALOID PYRROLIZIDINE – HẠI GAN", "txt": "Cây chứa alkaloid pyrrolizidine (adonifoline…), có thể gây độc gan; Dược điển quy định giới hạn adonifoline không quá 0,004%. Tránh dùng liều cao hoặc kéo dài, đặc biệt ở phụ nữ có thai hoặc cho con bú, trẻ nhỏ và người bệnh gan. Không nhầm với hoa Thiên lý (Telosma cordata) là rau ăn."},
"ngan-sai-ho":{"lv": "luu", "lab": "NHẦM VỚI SÀI HỒ", "txt": "Không phải Sài hồ (Bupleurum) – khác họ, khác công năng. Hàng lẫn ‘Sơn ngân sài hồ’ (rễ một số loài họ Cẩm chướng như Gypsophila) khá phổ biến. Theo giáo trình, cảm ngoại phong hàn hoặc huyết hư không có nhiệt thì không dùng."},
"ho-hoang-lien":{"lv": "luu", "lab": "RẤT ĐẮNG LẠNH, NHẦM HOÀNG LIÊN", "txt": "Rất đắng, tính lạnh: tỳ vị hư hàn, tiêu chảy do hư hàn không dùng. Không nhầm với Hoàng liên (Coptis) – khác họ, khác cây; Picrorhiza kurroa của Ấn Độ không phải loài Dược điển Trung Quốc nhận."},
"lau-lo":{"lv": "luu", "lab": "THẬN TRỌNG KHI CÓ THAI", "txt": "Dược điển ghi ‘thận trọng khi có thai’ (孕妇慎用). Lưu ý hàng lẫn ‘Vũ châu lậu lô’ (Echinops spp.); Dược điển 2020 chỉ nhận Kỳ châu lậu lô (Rhaponticum uniflorum)."},
"cu-mach":{"lv": "luu", "lab": "THẬN TRỌNG KHI CÓ THAI", "txt": "Dược điển ghi ‘thận trọng khi có thai’ (孕妇慎用); thực nghiệm kích thích co bóp tử cung, y văn xưa ghi ‘phá thai’. Theo giáo trình, tỳ thận hư, tiểu nhiều không do thấp nhiệt không dùng."},
"uy-linh-tien":{"lv": "luu", "lab": "LƯU Ý AN TOÀN", "txt": "Dược điển không ghi độc tính. Theo y văn, thể khí huyết hư yếu và phụ nữ có thai nên thận trọng; liều lớn có thể gây buồn nôn, tiêu chảy. Cây tươi chứa protoanemonin kích ứng da, niêm mạc nên không dùng rễ tươi chưa chế biến. Dây ông lão ở Việt Nam gồm nhiều loài Clematis, cần mua loại đã xác định loài."},
"hai-phong-dang":{"lv": "luu", "lab": "DỄ NHẦM LẪN", "txt": "Dược điển không ghi độc tính. Hải phong đằng (Piper kadsura) dễ bị nhầm hoặc thay bằng thân các loài Piper khác (như Thạch nam đằng) hay dây Kadsura, cũng không phải Thanh phong đằng. Theo y văn người âm hư hỏa vượng và phụ nữ có thai thận trọng."},
"thanh-phong-dang":{"lv": "manh", "lab": "DỄ DỊ ỨNG – TRÁNH NHẦM", "txt": "Hoạt chất sinomenine có thể làm giải phóng histamin: ngứa, nổi mẩn đỏ, buồn nôn, hạ huyết áp, hiếm gặp giảm bạch cầu, nhất là khi dùng liều cao hoặc chế phẩm chiết xuất. Người hen, cơ địa dị ứng, phụ nữ có thai nên thận trọng. Thanh phong đằng (Sinomenium) là cây họ Tiết dê, tuyệt đối không dùng nhầm Quảng phòng kỷ hay Quan mộc thông (Aristolochia, chứa aristolochic acid độc thận, gây ung thư)."},
"lo-lo-thong":{"lv": "luu", "lab": "LƯU Ý AN TOÀN", "txt": "Dược điển không ghi độc tính. Theo y văn, phụ nữ kinh nguyệt ra nhiều và phụ nữ có thai nên thận trọng hoặc kiêng dùng vì thuốc có tác dụng thông kinh, hoạt huyết."},
"than-can-thao":{"lv": "luu", "lab": "LƯU Ý AN TOÀN", "txt": "Dược điển không ghi độc tính. Theo y văn người có thai và người đang xuất huyết thận trọng. Thân cân thảo (Lycopodium japonicum) khác Thiên tằng tháp (Huperzia serrata, nguồn huperzine A) và bột bào tử Thạch tùng tử, không dùng lẫn."},
"thien-nien-kien":{"lv": "luu", "lab": "DỄ NHẦM LẪN", "txt": "Dược điển không ghi độc tính. Ở Việt Nam nhiều cây họ Ráy có hình thái gần giống, một số có thể chứa chất kích ứng hoặc độc, nên chỉ dùng vị đã xác định đúng loài Homalomena occulta. Theo y văn người âm hư nội nhiệt thận trọng."},
"tu-truong-khanh":{"lv": "luu", "lab": "SẮC SAU – DỄ NHẦM CHI", "txt": "Dược điển ghi cho vào sau (后下) vì tinh dầu dễ bay hơi, không sắc quá lâu. Theo y văn người thể hư yếu thận trọng. Cùng chi Cynanchum có nhiều vị khác (Bạch vi, Bạch tiền) công năng khác, không dùng lẫn."},
"ngoc-mi-tu":{"lv": "luu", "lab": "TƯƠNG TÁC THUỐC", "txt": "Râu ngô lợi tiểu, thực nghiệm hạ đường huyết và huyết áp, có kali. Người đang dùng thuốc lợi tiểu, hạ đường huyết, hạ huyết áp hoặc suy thận nên hỏi thầy thuốc. Không dùng râu ngô bị mốc."},
"ha-diep":{"lv": "luu", "lab": "LƯU Ý AN TOÀN", "txt": "Dược điển không ghi độc tính. Theo y văn người khí huyết hư, gầy yếu thận trọng. Trà lá sen giảm béo bán trên thị trường chưa có đủ chứng cứ lâm sàng, không nên uống liên tục dài ngày hoặc thay thế điều trị."},
"boi-lan":{"lv": "luu", "lab": "TRÁNH NHẦM LẪN", "txt": "Dược điển không ghi độc tính. Một số tài liệu nêu khả năng có alkaloid pyrrolizidine ở chi Eupatorium, chưa kết luận cho loài này, nên tránh dùng liều lớn kéo dài. Bội lan không phải Trạch lan (Lycopus), Hoa lan hay Cỏ lào (Chromolaena odorata). Theo y văn người âm hư huyết táo thận trọng."},
"tat-bat":{"lv": "luu", "lab": "NÓNG – TƯƠNG TÁC THUỐC", "txt": "Tính rất nóng và cay, Dược điển ghi liều nhỏ 1–3 g. Theo y văn người âm hư hỏa vượng, có nhiệt không dùng; thận trọng khi có thai. Piperine trong thực nghiệm làm tăng sinh khả dụng của nhiều thuốc nên có thể tương tác với thuốc chuyển hóa qua gan."},
"son-nai":{"lv": "luu", "lab": "LƯU Ý AN TOÀN", "txt": "Dược điển không ghi độc tính. Tính cay ấm: theo y văn người âm hư hỏa vượng, có nhiệt và phụ nữ có thai thận trọng. Không nhầm với Cao lương khương, Gừng hay Nghệ."},
"tu-to-tu":{"lv": "luu", "lab": "NHUẬN TRÀNG", "txt": "Dược điển không ghi độc tính. Theo y văn có tác dụng nhuận tràng: người tỳ hư tiêu chảy, khí hư ho lâu thận trọng hoặc không dùng. Người dị ứng họ Hoa môi lưu ý."},
"huong-duyen":{"lv": "luu", "lab": "TRÁNH NHẦM LẪN", "txt": "Dược điển không ghi độc tính. Hương duyên (Thanh yên) khác Phật thủ (Citrus medica var. sarcodactylis), Bưởi và Chanh. Theo y văn người âm hư huyết táo và phụ nữ có thai khí hư thận trọng."},
"thanh-bi":{"lv": "luu", "lab": "PHÁ KHÍ MẠNH", "txt": "Dược điển không ghi độc tính. Tính phá khí mạnh: theo y văn người khí hư, tỳ vị yếu và phụ nữ có thai thận trọng. Thanh bì (quả non) khác Trần bì (vỏ quả chín), Chỉ thực, Chỉ xác."},
"dai-phuc-bi":{"lv": "luu", "lab": "KHÁC TÂN LANG", "txt": "Dược điển không ghi độc tính. Đại phúc bì là vỏ quả cau, khác Tân lang (hạt cau); nhai trầu cau lâu dài liên quan đến ung thư khoang miệng nên không nên suy ra Đại phúc bì thuốc vô hại tuyệt đối. Theo y văn người khí hư thể yếu thận trọng; không dùng hàng ẩm mốc."},
"sa-uyen-tu":{"lv": "luu", "lab": "DỄ NHẦM TÊN: SA UYỂN ≠ BẠCH TẬT LÊ", "txt": "Dược điển không ghi cảnh báo riêng. Sa uyển tử (còn gọi Đồng tật lê, hạt Astragalus complanatus) khác hẳn Bạch tật lê (Tribulus terrestris, gai ma vương); hai vị có công dụng khác nhau, không dùng lẫn. Theo giáo trình, người âm hư hỏa vượng hoặc tiểu tiện bí, khó không nên dùng."},
"lien-tu-tam":{"lv": "luu", "lab": "TÍNH LẠNH, VỊ ĐẮNG", "txt": "Dược điển không ghi cảnh báo riêng. Tim sen rất đắng, tính lạnh: dùng nhiều hoặc kéo dài dễ lạnh bụng, tiêu chảy, nhất là người tỳ vị hư hàn. Thực nghiệm có tác dụng hạ áp nên người huyết áp thấp hoặc đang dùng thuốc hạ áp, thuốc an thần cần hỏi thầy thuốc."},
"ma-hoang-can":{"lv": "luu", "lab": "ĐỪNG NHẦM VỚI MA HOÀNG", "txt": "Ma hoàng căn (rễ) cầm mồ hôi, trái hẳn với Ma hoàng (thân) phát hãn và chứa nhiều ephedrine làm tăng huyết áp, tim nhanh. Hai vị khác nhau hoàn toàn, không dùng lẫn. Không dùng khi đang cảm mạo, sợ lạnh, sốt chưa ra mồ hôi (theo giáo trình). Dược điển không ghi mục chú ý riêng."},
"phu-tieu-mach":{"lv": "luu", "lab": "CHỨA GLUTEN / DỊ ỨNG LÚA MÌ", "txt": "Hạt lúa mì chứa gluten: người bệnh celiac hoặc dị ứng lúa mì cần tránh. Theo giáo trình, đang có biểu chứng ngoại cảm chưa giải thì không dùng."},
"ngu-boi-tu":{"lv": "luu", "lab": "TANNIN CAO", "txt": "Dược điển không ghi cảnh báo riêng. Ngũ bội tử giàu tannin (Dược điển yêu cầu không dưới 50%): dùng liều lớn hoặc kéo dài có thể kích ứng dạ dày, gây táo bón, và thực nghiệm báo cáo tannin liều cao có thể tổn thương gan thận. Tannin cũng làm giảm hấp thu sắt và một số thuốc. Không dùng khi ho do ngoại cảm hoặc tiêu chảy do thấp nhiệt mới phát (theo giáo trình)."},
"thach-luu-bi":{"lv": "luu", "lab": "KHÔNG NHẦM VỎ RỄ LỰU", "txt": "Dược điển không ghi cảnh báo riêng cho vỏ quả. Vỏ rễ lựu (dùng tẩy sán) là vị khác, nhiều alkaloid hơn và độc hơn, có thể gây chóng mặt, nhìn mờ, co giật khi quá liều; không tự dùng. Vỏ quả cũng không nên dùng liều cao hoặc kéo dài (tannin nhiều dễ táo bón, kích ứng dạ dày). Tiêu chảy, kiết lỵ mới phát chưa nên dùng (theo giáo trình)."},
"bach-bien-dau":{"lv": "luu", "lab": "PHẢI NẤU CHÍN KỸ", "txt": "Dược điển không ghi cảnh báo riêng. Theo y văn, hạt đậu ván sống hoặc nấu chưa chín chứa lectin và có thể chứa glycoside sinh cyanide, gây buồn nôn, nôn, đau bụng, chóng mặt. Chỉ dùng hạt đã nấu chín hoặc sao kỹ."},
"thu-o-dang":{"lv": "luu", "lab": "THẬN TRỌNG VỚI GAN", "txt": "Dược điển không ghi cảnh báo riêng cho thân dây. Đã có báo cáo tổn thương gan liên quan đến củ Hà thủ ô (cùng cây); dữ liệu riêng cho thân dây còn ít. Người có bệnh gan hoặc đang dùng thuốc độc gan nên thận trọng; nếu mệt, vàng da, nước tiểu sẫm màu cần ngừng ngay và đi khám. Hà thủ ô trắng (Streptocaulon juventas) là cây khác."},
"la-bo-ma-diep":{"lv": "luu", "lab": "HẠ ÁP, LỢI TIỂU, GLYCOSIDE TIM", "txt": "Dược điển không ghi cảnh báo riêng. Cây có tác dụng hạ huyết áp, lợi tiểu và theo tài liệu chứa một lượng nhỏ glycoside trợ tim; dùng liều cao hoặc cùng thuốc hạ áp, thuốc lợi tiểu, thuốc tim (như digoxin) có thể gây tụt huyết áp, nhịp tim chậm, rối loạn điện giải. Người có bệnh tim, huyết áp thấp, phụ nữ có thai cần hỏi thầy thuốc."},
"bac-sa-sam":{"lv": "luu", "lab": "KHÔNG DÙNG CHUNG VỚI LÊ LÔ", "txt": "Dược điển ghi: không dùng chung với Lê lô (不宜与藜芦同用). Lê lô (Veratrum) chứa alkaloid độc tim và thần kinh, và nằm trong nhóm tương phản ‘thập bát phản’ của y học cổ truyền với các loại sâm, trong đó có Sa sâm. Không tự phối hai vị này."},
"nam-sa-sam":{"lv": "luu", "lab": "KHÔNG DÙNG CHUNG VỚI LÊ LÔ", "txt": "Dược điển ghi: không dùng chung với Lê lô (不宜与藜芦同用). Lê lô (Veratrum) chứa alkaloid độc tim và thần kinh, và nằm trong nhóm tương phản ‘thập bát phản’ của y học cổ truyền với các loại sâm, trong đó có Sa sâm. Không tự phối hai vị này."},
"tien-mao":{"lv": "doc", "lab": "CÓ ĐỘC (有毒)", "txt": "Dược điển ghi tính nóng, có độc (辛、热；有毒). Dùng liều cao hoặc kéo dài, theo y văn có thể gây khô miệng, nóng trong, buồn nôn, nôn, đau bụng; thực nghiệm báo cáo tổn thương gan thận ở liều cao. Không tự ngâm rượu uống lâu dài. Người âm hư hỏa vượng, có bệnh gan thận, phụ nữ có thai nên tránh. Chỉ dùng đúng liều 3–10 g/ngày theo hướng dẫn của thầy thuốc, loại đã chế từ nơi tin cậy."},
"hach-dao-nhan":{"lv": "luu", "lab": "DỊ ỨNG HẠT CÂY / NHÂN ÔI MỐC", "txt": "Dược điển không ghi cảnh báo riêng. Hạt óc chó là tác nhân gây dị ứng thực phẩm phổ biến, có thể gây phản ứng nặng kể cả sốc phản vệ: người dị ứng hạt cây cần tránh hoàn toàn. Nhân ôi, mốc (nguy cơ độc tố nấm mốc) phải bỏ; Dược điển giới hạn chỉ số axit, carbonyl, peroxid. Đàm nhiệt, đại tiện lỏng không nên dùng (theo giáo trình)."},
"xuyen-nguu-tat":{"lv": "luu", "lab": "THẬN TRỌNG KHI CÓ THAI", "txt": "Dược điển ghi 孕妇慎用 (thận trọng khi có thai). Vị thuốc hoạt huyết thông kinh, đi xuống, có thể kích thích tử cung; phụ nữ có thai và người kinh nguyệt ra nhiều nên hỏi thầy thuốc. Dễ nhầm với Hoài ngưu tất (Achyranthes bidentata) và Ngưu tất nam (cỏ xước, Achyranthes aspera) là các vị khác."},
"huyet-kiet":{"lv": "luu", "lab": "HÀNG GIẢ, DỄ NHẦM NGUỒN", "txt": "Huyết kiệt thật (Daemonorops draco) rất khan hiếm nên hàng giả (nhựa thông nhuộm màu, trộn bột màu) phổ biến. ‘Máu rồng’ hay ‘huyết kiệt’ còn dùng gọi nhựa của Dracaena cochinchinensis (Huyết giác), Dracaena cinnabari… là các nguồn khác, không phải nguồn Dược điển. Theo giáo trình: phụ nữ có thai và đang hành kinh thận trọng; không có ứ huyết thì không dùng."},
"mot-duoc":{"lv": "luu", "lab": "CÓ THAI, VỊ YẾU", "txt": "Dược điển ghi 孕妇及胃弱者慎用 (thận trọng với phụ nữ có thai và người vị yếu). Dùng sống dễ gây buồn nôn, nôn, đau dạ dày; nên dùng loại đã chế giấm (醋沒藥) và liều thấp, dùng cùng thầy thuốc."},
"giang-huong":{"lv": "luu", "lab": "NGUỒN GỖ, HÀNG GIẢ", "txt": "Dược điển chỉ nhận Dalbergia odorifera (Giáng hương đàn, Hải Nam). Hàng giả hoặc gỗ thay thế (gỗ nhuộm, gỗ tẩm hương) phổ biến; ‘giáng hương’ trong tiếng Việt thường chỉ Pterocarpus macrocarpus, là loài khác. Các loài Dalbergia nằm trong phụ lục CITES nên nguồn nguyên liệu cần hợp pháp."},
"nguyet-qui-hoa":{"lv": "luu", "lab": "LIỀU CAO, CÓ THAI (THEO Y VĂN)", "txt": "Dược điển không ghi cảnh báo riêng. Theo giáo trình: hoạt huyết điều kinh nên phụ nữ có thai thận trọng; dùng liều cao hoặc kéo dài dễ gây đau bụng, tiêu chảy. Không nhầm với Mai khôi hoa (Rosa rugosa) hoặc các giống hồng cảnh phun thuốc trừ sâu."},
"lang-tieu-hoa":{"lv": "luu", "lab": "KIÊNG KHI CÓ THAI (THEO GIÁO TRÌNH)", "txt": "Vị hoạt huyết phá ứ khá mạnh; theo giáo trình phụ nữ có thai không dùng. Phấn hoa dính vào mắt có thể gây kích ứng (theo y văn dân gian). Không nhầm với Pyrostegia venusta (hoa khèn, cùng tên ‘đăng tiêu’ trong dân gian)."},
"xuyen-son-long":{"lv": "luu", "lab": "DỊ ỨNG KHI GIA CÔNG", "txt": "Dược điển ghi: khi nghiền, chế biến cần chú ý bảo hộ để tránh dị ứng (粉碎加工时，注意防护，以免发生过敏反应). Nên đeo khẩu trang khi xay bột; dùng liều đúng, không ngâm rượu uống quá nhiều. Không nhầm với các loài Dioscorea khác (Tỳ giải, Củ nâu, Củ mài)."},
"quyen-ba":{"lv": "luu", "lab": "THẬN TRỌNG KHI CÓ THAI", "txt": "Dược điển ghi 孕妇慎用 (thận trọng khi có thai). Dùng sống thiên về hoạt huyết thông kinh nên phụ nữ có thai không tự dùng; sao than thì thiên về cầm máu. Ở Việt Nam ‘Quyển bá’ trong dân gian còn chỉ các Selaginella khác (như Thạch thượng bá), không đồng nhất với dược liệu này."},
"mach-nha":{"lv": "luu", "lab": "LÀM GIẢM SỮA", "txt": "Dược điển ghi công năng ‘hồi sữa’ (回乳): liều lớn sao (đến 60 g) dùng để cai sữa, nên phụ nữ đang cho con bú không muốn mất sữa không dùng liều lớn. ‘Mạch nha’ trong kẹo, đường mạch nha (malt syrup) là thực phẩm khác với vị thuốc này."},
"bach-tien":{"lv": "luu", "lab": "KÍCH ỨNG DẠ DÀY, DỄ NHẦM TÊN", "txt": "Dược điển không ghi cảnh báo riêng. Theo giáo trình: có thể kích ứng dạ dày gây buồn nôn, người viêm loét dạ dày thận trọng; ho khan do âm hư không dùng. Dễ nhầm với Bạch vi (Cynanchum atratum) và Tiền hồ (Peucedanum), là các vị khác."},
"mieu-trao-thao":{"lv": "luu", "lab": "CÂY TƯƠI KÍCH ỨNG (THEO Y VĂN)", "txt": "Dược điển không ghi cảnh báo riêng; chỉ dùng củ khô đã chế. Theo y văn, họ Mao lương (Ranunculaceae) thường chứa ranunculin, khi giã cây tươi sinh protoanemonin gây phồng rộp da, bỏng rát miệng họng, nôn. Không giã đắp tươi lâu trên da; không nhầm với Mao cấn (Ranunculus japonicus) hoặc các loài mao lương độc khác."},
"tao-giac-thich":{"lv": "luu", "lab": "CÓ THAI, MỤN ĐÃ VỠ (THEO Y VĂN)", "txt": "Dược điển không ghi cảnh báo riêng. Theo giáo trình: tính ‘xuyên thấu’ mạnh nên phụ nữ có thai thận trọng; mụn nhọt đã vỡ mủ thì không dùng. Dược điển chỉ nhận Gleditsia sinensis; gai của Bồ kết Việt Nam (Gleditsia fera) dùng theo kinh nghiệm dân gian, chưa được thống nhất."},
"bang-dai-hai":{"lv": "luu", "lab": "KHÔNG LẠM DỤNG LÀM TRÀ", "txt": "Dược điển không ghi cảnh báo riêng. Theo y văn: tính lạnh, uống như trà thường xuyên hoặc dùng nhiều dễ gây tiêu chảy, đầy bụng; người tỳ vị hư hàn, ho do lạnh (đờm loãng, sợ lạnh) không nên dùng. Chọn hạt sạch, không mốc."},
"dinh-lich-tu":{"lv": "luu", "lab": "TRỢ TIM, THẬN TRỌNG DÙNG CHUNG", "txt": "Dược điển không ghi cảnh báo riêng. Theo y văn, hạt Nam đình lịch chứa glycoside trợ tim (như helveticoside), nên thận trọng khi dùng chung digoxin hoặc thuốc trợ tim, và với người loạn nhịp. Tính rất lạnh, mạnh: người phế hư, tỳ hư thủy thũng, suy yếu không có thực chứng không dùng."},
"mau-dinh-huong":{"lv": "luu", "lab": "KỴ DÙNG CHUNG UẤT KIM", "txt": "Dược điển ghi không nên dùng chung Mẫu đinh hương với Uất kim (cũng như Đinh hương – Uất kim). Tinh dầu eugenol nguyên chất liều cao có thể kích ứng niêm mạc và gây độc gan trong thực nghiệm; không uống tinh dầu."},
"hong-dau-khau":{"lv": "luu", "lab": "NHẦM HẠT ĐẬU ĐỎ ĐỘC", "txt": "Hồng đậu khấu là quả của Riềng nếp (Alpinia galanga), không phải ‘hạt đậu đỏ’. Không nhầm với Tương tư tử (Abrus precatorius, hạt đỏ chấm đen chứa abrin cực độc) hay hạt Ormosia; cũng khác Nhục đậu khấu, Bạch đậu khấu và Thảo đậu khấu."},
"que-chi":{"lv": "luu", "lab": "THẬN TRỌNG KHI CÓ THAI", "txt": "Dược điển ghi thận trọng khi có thai. Tính ấm cay: không dùng trong chứng nhiệt (sốt cao, khát, họng đỏ), âm hư hỏa vượng, người dễ chảy máu do nhiệt. Coumarin trong quế Cassia dùng liều cao kéo dài có thể gây hại gan ở người nhạy cảm."},
"thich-ngu-gia":{"lv": "luu", "lab": "NHẦM NGŨ GIA BÌ – HƯƠNG GIA BÌ", "txt": "Thích ngũ gia là rễ/thân rễ Acanthopanax senticosus. Không nhầm với Hương gia bì (Periploca sepium) có glycoside trợ tim, dùng sai có thể độc. Theo y văn, thận trọng khi tăng huyết áp nặng; dữ liệu về tương tác với warfarin, digoxin còn hạn chế."},
"tay-hong-hoa":{"lv": "luu", "lab": "THẬN TRỌNG KHI CÓ THAI", "txt": "Dược điển ghi thận trọng khi có thai. Vị thuốc đắt tiền, hay bị làm giả (râu ngô nhuộm, sợi Hồng hoa). Kinh nguyệt nhiều, đang chảy máu hoặc đang dùng thuốc chống đông cần hỏi thầy thuốc; liều cao hơn nhiều so với liều thường có thể gây buồn nôn, chóng mặt, chảy máu."},
"tho-moc-huong":{"lv": "luu", "lab": "NHẦM THANH MỘC HƯƠNG; DỊ ỨNG HỌ CÚC", "txt": "Ở một số nơi tên ‘Thổ thanh mộc hương/Thanh mộc hương’ chỉ rễ Aristolochia chứa acid aristolochic độc thận — tuyệt đối không dùng thay Thổ mộc hương (Inula helenium). Sesquiterpene lactone có thể gây viêm da, dị ứng ở người nhạy cảm họ Cúc."},
"quang-kim-tien-thao":{"lv": "luu", "lab": "NHẦM KIM TIỀN THẢO", "txt": "Dược điển chỉ dùng Desmodium styracifolium (lá mặt dưới phủ lông tơ xám trắng). Kim tiền thảo Tứ Xuyên (Lysimachia christinae) và Liên tiền thảo (Glechoma longituba) là hai cây khác, ở Việt Nam đôi khi bị gọi chung là ‘Kim tiền thảo’. Sỏi lớn gây đau quặn hoặc tắc cần đi khám."},
"ho-truong":{"lv": "luu", "lab": "THẬN TRỌNG KHI CÓ THAI", "txt": "Dược điển ghi thận trọng khi có thai. Chứa anthraquinone: liều cao có thể gây buồn nôn, tiêu chảy; tỳ vị hư hàn, kinh nguyệt ra nhiều thận trọng. Dữ liệu an toàn dài hạn với chế phẩm resveratrol liều cao chiết từ cây này còn thiếu."},
"dien-co-hoang":{"lv": "luu", "lab": "CHƯA ĐỐI CHIẾU DƯỢC ĐIỂN", "txt": "Chưa đối chiếu được Dược điển; liều và tính vị theo giáo trình. Không tự dùng thay điều trị bệnh gan. Khác Hypericum perforatum (St John’s wort) vốn nổi tiếng tương tác thuốc; chưa rõ loài này có tương tác tương tự hay không."},
"ke-cot-thao":{"lv": "manh", "lab": "PHẢI BỎ QUẢ ĐẬU – HẠT CÓ ĐỘC", "txt": "Dược điển chỉ dùng thân lá và yêu cầu bỏ quả đậu khi chế biến; theo y văn hạt trong quả đậu có độc. Loài họ hàng Cam thảo dây/Tương tư tử (Abrus precatorius) có hạt chứa abrin cực độc. Tuyệt đối không dùng hay nhai hạt, chỉ mua dược liệu đã bỏ quả. Nếu nôn, đau bụng, tiêu chảy ra máu sau khi dùng, đi cấp cứu ngay."},
"chi-xac":{"lv": "luu", "lab": "THẬN TRỌNG KHI CÓ THAI", "txt": "Dược điển ghi thận trọng khi có thai. Chứa synephrine (alkaloid kiểu giao cảm): thận trọng khi cao huyết áp, rối loạn nhịp tim hoặc đang dùng thuốc kích thích. Chỉ xác nhẹ hơn Chỉ thực, không dùng lẫn."},
"qua-lau-tu":{"lv": "luu", "lab": "KỴ NHÓM Ô ĐẦU – PHỤ TỬ", "txt": "Dược điển ghi không dùng chung với Xuyên ô, Chế xuyên ô, Thảo ô, Chế thảo ô, Phụ tử (nằm trong nhóm ‘thập bát phản’: Ô đầu phản Qua lâu). Tính hàn trơn tràng: tỳ vị hư hàn, đại tiện lỏng không dùng."},
"qua-lau-bi":{"lv": "luu", "lab": "KỴ NHÓM Ô ĐẦU – PHỤ TỬ", "txt": "Dược điển ghi không dùng chung với Xuyên ô, Chế xuyên ô, Thảo ô, Chế thảo ô, Phụ tử (nằm trong nhóm ‘thập bát phản’: Ô đầu phản Qua lâu). Tính hàn: tỳ vị hư hàn, đờm trắng loãng thận trọng."},
"khuong-hoat":{"lv": "luu", "lab": "DỄ NHẦM VỚI ĐỘC HOẠT", "txt": "Khương hoạt (Notopterygium) và Độc hoạt (Angelica pubescens) là hai vị khác nhau dù cùng họ Hoa tán, hay bị gọi lẫn. Theo giáo trình, tính cay ấm khô táo nên người âm hư huyết thiếu không nên dùng; liều lớn dễ buồn nôn. Nguồn dược liệu hoang dã khan hiếm."},
"kinh-gioi-tuy":{"lv": "luu", "lab": "TRÙNG TÊN ‘KINH GIỚI’", "txt": "Kinh giới tuệ (Schizonepeta tenuifolia, Trung Quốc) khác với ‘Kinh giới’ làm rau thơm ở Việt Nam (Elsholtzia ciliata); thành phần pulegone ở liều cao trong thực nghiệm có thể gây hại gan. Chỉ dùng đúng liều và đúng loài."},
"tay-ha-lieu":{"lv": "luu", "lab": "KHÔNG DÙNG KHI SỞI ĐÃ MỌC ĐỦ", "txt": "Theo y văn, sởi đã mọc đủ thì không dùng; dùng quá liều dễ làm người bồn chồn. Dược điển ghi dùng uống 3–6 g, ngoài dùng sắc nước xông rửa."},
"te-tan":{"lv": "manh", "lab": "CHỨA ACID ARISTOLOCHIC – DÙNG ĐÚNG LIỀU", "txt": "Tế tân thuộc họ Mã đâu linh, chứa acid aristolochic I (Dược điển 2020 quy định chỉ tiêu giới hạn không quá 0,001% và yêu cầu bỏ phần trên mặt đất). Dược điển ghi: không dùng chung với Lê lô. Liều uống 1–3 g, tán bột mỗi lần 0,5–1 g; không dùng kéo dài; bệnh gan thận nên hỏi thầy thuốc. Dễ nhầm với Đỗ hành (Thổ tế tân), Từ trường khanh và các loài Aristolochia."},
"kim-qua-lam":{"lv": "luu", "lab": "VỊ RẤT ĐẮNG LẠNH, DỄ NHẦM CỦ ĐẮNG KHÁC", "txt": "Vị rất đắng, tính lạnh, tỳ vị hư hàn không nên dùng, không dùng kéo dài (theo giáo trình). Nhiều loài Tinospora, Stephania họ Tiết dê có củ giống nhau và cùng gọi là ‘Địa khổ đảm’; chỉ dùng đúng loài ghi trong Dược điển."},
"thien-quy-tu":{"lv": "luu", "lab": "DỄ NHẦM CỦ HỌ MAO LƯƠNG ĐỘC", "txt": "Thiên quỳ tử thuộc họ Mao lương, họ có nhiều củ độc (như các loài Aconitum); củ nhỏ nâu đen dễ nhầm. Chỉ dùng dược liệu đã xác định đúng loài, không tự hái ngoài thiên nhiên. Tính lạnh, tỳ vị hư hàn không nên dùng (theo giáo trình)."},
"cong-lao-moc":{"lv": "luu", "lab": "CHỨA BERBERIN, TỲ HƯ HÀN KIÊNG", "txt": "Chứa nhóm alkaloid berberin; tính rất đắng lạnh, tỳ vị hư hàn không nên dùng; thận trọng khi có thai và với trẻ sơ sinh (theo y văn về berberin). Dễ nhầm với Hoàng bá, Tam khỏa châm và các loài Mahonia khác."},
"hoang-dang":{"lv": "luu", "lab": "LIỀU DƯỢC ĐIỂN CAO, TÊN GỌI DỄ NHẦM", "txt": "Liều Dược điển là 30–60 g/ngày (tương đối lớn) nên cần theo chỉ định thầy thuốc; tính rất đắng lạnh, tỳ vị hư hàn không nên dùng. Ở Việt Nam ‘Hoàng đằng’, ‘dây vàng’ có thể chỉ nhiều loài dây leo họ Tiết dê khác nhau."},
"son-ngan-hoa":{"lv": "luu", "lab": "KHÁC KIM NGÂN HOA, KHÔNG THAY TÙY TIỆN", "txt": "Sơn ngân hoa (4 loài Lonicera) và Kim ngân hoa (Lonicera japonica) là hai vị riêng trong Dược điển với thành phần khác nhau; không ghi nhầm khi bốc thuốc. Tính lạnh, tỳ vị hư hàn, tiêu chảy không nên dùng (theo giáo trình)."},
"bac-dau-can":{"lv": "doc", "lab": "TIỂU ĐỘC THEO DƯỢC ĐIỂN", "txt": "Dược điển ghi tính vị ‘có độc nhẹ’ (小毒), liều 3–9 g. Theo y văn, dùng quá liều có thể gây buồn nôn, nôn, đau bụng, chóng mặt, hạ huyết áp. Không nhầm với Sơn đậu căn (Sophora tonkinensis, họ Đậu, cũng có độc) hoặc các dược liệu ‘đậu căn’, ‘phòng kỷ’ khác."},
"quan-hoang-ba":{"lv": "luu", "lab": "KHÁC HOÀNG BÁ; KHÔNG NHẦM QUAN MỘC THÔNG", "txt": "Quan hoàng bá (P. amurense) khác Hoàng bá (Xuyên hoàng bá, P. chinense). Không nhầm với Quan mộc thông (Aristolochia manshuriensis), dược liệu chứa acid aristolochic đã bị loại khỏi Dược điển, chỉ giống nhau chữ ‘Quan’. Chứa berberin: thận trọng khi có thai và trẻ sơ sinh; tỳ vị hư hàn không dùng (theo y văn)."},
"kho-moc":{"lv": "doc", "lab": "TIỂU ĐỘC THEO DƯỢC ĐIỂN", "txt": "Dược điển ghi tính vị ‘có độc nhẹ’ (小毒); liều cành 3–4,5 g, lá 1–3 g. Theo y văn, dùng quá liều có thể gây buồn nôn, nôn, đau bụng; phụ nữ có thai, trẻ nhỏ nên hỏi thầy thuốc; không dùng kéo dài hoặc ngâm rượu tùy tiện."},
"dam-dau-xi":{"lv": "luu", "lab": "KHÁC ĐẬU XỊ MUỐI; DỄ MỐC", "txt": "Đạm đậu xị là đậu đen lên men với nước sắc Dâu và Thanh hao, không muối, khác đậu xị muối dùng làm gia vị. Sản phẩm lên men dễ nhiễm mốc nếu bảo quản ẩm; không dùng thuốc đã mốc lạ hoặc ôi thiu (theo y văn)."},
"thanh-dai":{"lv": "luu", "lab": "NÊN DÙNG HOÀN TÁN; CÓ THỂ PHA TẠP", "txt": "Dược điển ghi nên dùng dạng hoàn, tán, liều 1–3 g. Có báo cáo ca bệnh về tổn thương gan và tăng áp động mạch phổi khi uống kéo dài (theo y văn). Bột có thể bị pha thuốc nhuộm hoặc canxi cacbonat (Dược điển kiểm tra thuốc nhuộm tan trong nước); chỉ mua nơi tin cậy."},
"thung-tiet-phong":{"lv": "luu", "lab": "DẠNG TIÊM TỪNG CÓ PHẢN ỨNG BẤT LỢI", "txt": "Dược điển không ghi độc tính; dạng tiêm từng có báo cáo phản ứng bất lợi (theo y văn). Phụ nữ có thai nên hỏi thầy thuốc vì dữ liệu an toàn còn ít."},
"tho-boi-mau":{"lv": "luu", "lab": "KHÔNG PHẢI BỐI MẪU (FRITILLARIA)", "txt": "Thổ bối mẫu (họ Bầu bí) là dược liệu khác hoàn toàn với các loại Bối mẫu chi Fritillaria; công năng khác nhau, không dùng thay nhau. Chứa saponin có thể kích ứng niêm mạc (theo y văn)."},
"tam-khoa-cham":{"lv": "doc", "lab": "CÓ ĐỘC THEO DƯỢC ĐIỂN", "txt": "Dược điển ghi tính vị ‘có độc’ (有毒), liều 9–15 g; không tự dùng quá liều hoặc kéo dài. Theo y văn về berberin: liều cao có thể gây buồn nôn, nôn, tiêu chảy; thận trọng khi có thai và trẻ sơ sinh. Dễ nhầm với Công lao mộc, Hoàng liên, Hoàng bá, Hoàng đằng."},
"thong-thao":{"lv": "luu", "lab": "THẬN TRỌNG KHI CÓ THAI, DỄ NHẦM MỘC THÔNG", "txt": "Dược điển ghi: thận trọng khi có thai. Thông thảo (ruột Tetrapanax papyrifer) khác Mộc thông và Tiểu thông thảo; không dùng nhầm Quan mộc thông (Aristolochia manshuriensis) chứa axit aristolochic gây độc thận."},
"tieu-thong-thao":{"lv": "luu", "lab": "DỄ NHẦM VỚI THÔNG THẢO, MỘC THÔNG", "txt": "Dược điển cho ba nguồn gốc (hai loài Stachyurus và Helwingia japonica) và không ghi chú ý. Cần phân biệt với Thông thảo (Tetrapanax) và Mộc thông; tuyệt đối không dùng nhầm Quan mộc thông chứa axit aristolochic."},
"thach-vi":{"lv": "luu", "lab": "LÔNG SAO DƯỚI LÁ", "txt": "Dược điển không ghi chú ý. Theo y văn, lông sao ở mặt dưới lá có thể gây kích ứng cổ họng nếu chưa rửa, sàng sạch; không nhầm với các dương xỉ bám đá khác."},
"mien-ty-giai":{"lv": "luu", "lab": "DỄ NHẦM CÁC LOÀI DIOSCOREA", "txt": "Dược điển không ghi chú ý. Tên Tỳ giải bao gồm nhiều loài Dioscorea (Miên tỳ giải, Phấn tỳ giải và loài địa phương), cần mua đúng nguồn; người thận hư di tinh không có thấp nhiệt thận trọng (theo giáo trình)."},
"phan-ty-giai":{"lv": "luu", "lab": "DỄ NHẦM CÁC LOÀI DIOSCOREA", "txt": "Dược điển không ghi chú ý. Tên Tỳ giải bao gồm nhiều loài Dioscorea, cần mua đúng nguồn; người thận hư di tinh không có thấp nhiệt thận trọng (theo giáo trình)."},
"dong-quy-qua":{"lv": "luu", "lab": "TRƠN LỢI, THẬN TRỌNG KHI CÓ THAI", "txt": "Dược điển không ghi chú ý. Theo y văn, hạt trơn lợi nên phụ nữ có thai và người tỳ vị hư hàn tiêu chảy cần thận trọng; không nhầm với hạt Thục quỳ hay hạt Abutilon theophrasti."},
"lieu-dai-thanh-diep":{"lv": "luu", "lab": "TÍNH ĐẠI HÀN, DỄ NHẦM ĐẠI THANH DIỆP", "txt": "Dược điển không ghi chú ý. Theo giáo trình, tính hàn nên người tỳ vị hư hàn, tiêu chảy tránh dùng; không nhầm với Đại thanh diệp (Isatis indigotica) hay lá Chàm khác."},
"bat-khiet":{"lv": "luu", "lab": "DỄ NHẦM CÁC LOÀI SMILAX", "txt": "Dược điển không ghi chú ý. Tên gọi dân gian ‘Kim cang’, ‘Khúc khắc’ chỉ nhiều loài Smilax; không nhầm với Thổ phục linh (Smilax glabra). Người can thận âm hư thận trọng (theo giáo trình)."},
"hai-dong-bi":{"lv": "luu", "lab": "CHƯA CÓ SỐ LIỆU DƯỢC ĐIỂN", "txt": "Không xác nhận được chuyên luận trong Dược điển 2020. Chi Erythrina chứa alkaloid tác dụng lên thần kinh (chủ yếu ở hạt); không tự dùng liều cao. Dễ nhầm với ‘Hải đồng’ (Pittosporum). Theo y văn."},
"du-tung-tiet":{"lv": "luu", "lab": "ÂM HƯ HUYẾT TÁO THẬN TRỌNG", "txt": "Dược điển ghi: thận trọng với người âm hư huyết táo."},
"loc-ham-thao":{"lv": "luu", "lab": "DỄ NHẦM TÊN GỌI DÂN GIAN", "txt": "Dược điển không ghi chú ý. Tên Lộc hàm thảo/Lộc đề thảo trong dân gian có thể chỉ nhiều loài; cần mua đúng nguồn, phụ nữ có thai thận trọng (theo y văn)."},
"nao-duong-hoa":{"lv": "doc", "lab": "ĐỘC MẠNH (大毒), KHÔNG TỰ DÙNG", "txt": "Dược điển ghi: có độc lớn, không nên dùng nhiều và lâu; người thể trạng hư yếu và phụ nữ có thai cấm dùng. Liều Dược điển chỉ 0,6–1,5 g, ngâm rượu hoặc nhập hoàn tán. Hoa chứa grayanotoxin; theo y văn ngộ độc gây buồn nôn, nôn, chảy nước dãi, chóng mặt, nhịp tim chậm, tụt huyết áp, khó thở, cần cấp cứu ngay. Không dùng thay các loài hoa đỗ quyên ăn được."},
"to-su-ma":{"lv": "manh", "lab": "CÓ ĐỘC NHẸ, KÍCH ỨNG MẠNH", "txt": "Không có chuyên luận Dược điển 2020; theo y văn/tiêu chuẩn địa phương là vị có độc nhẹ. Chi Daphne chứa hoạt chất kích ứng da, niêm mạc; phụ nữ có thai tuyệt đối không dùng, người dạ dày yếu thận trọng. Chỉ dùng theo chỉ định thầy thuốc."},
"luong-dien-cham":{"lv": "doc", "lab": "ĐỘC NHẸ (小毒), KHÔNG QUÁ LIỀU", "txt": "Dược điển ghi: có độc nhẹ; không dùng quá liều; kiêng dùng cùng thức ăn có vị chua. Liều uống Dược điển 5–10 g/ngày. Theo y văn, phụ nữ có thai nên tránh; alkaloid nhóm benzophenanthridin có thể gây độc khi quá liều."},
"cuu-ly-huong":{"lv": "doc", "lab": "ĐỘC NHẸ (小毒)", "txt": "Dược điển ghi vị có độc nhẹ nhưng không ghi mục chú ý. Dùng đúng liều 6–12 g/ngày, không dùng kéo dài; theo giáo trình phụ nữ có thai thận trọng. Không nhầm với Thiên lý (Telosma cordata) hay Nguyệt quý hoa (月季花)."},
"dia-phong-bi":{"lv": "doc", "lab": "ĐỘC NHẸ (小毒), DỄ NHẦM ILLICIUM ĐỘC", "txt": "Dược điển ghi vị có độc nhẹ nhưng không ghi mục chú ý. Chi Illicium có loài rất độc (Mãng thảo, Hồng hồi), tuyệt đối không dùng nhầm; theo y văn phụ nữ có thai và trẻ em thận trọng. Loài quý hiếm, cần nguồn gốc rõ ràng."},
"luong-dau-tiem":{"lv": "doc", "lab": "CÓ ĐỘC (有毒), CẤM KHI CÓ THAI", "txt": "Dược điển ghi: vị có độc; phụ nữ có thai cấm dùng. Liều Dược điển 1–3 g/ngày. Theo y văn họ Mao lương chứa saponin kích ứng, quá liều có thể gây tổn thương niêm mạc, tan huyết; không dùng nhầm Ô đầu, Phụ tử, Thảo ô."},
"man-son-hong":{"lv": "luu", "lab": "ĐỪNG NHẦM VỚI ĐỖ QUYÊN KHÁC", "txt": "Dược điển không ghi mục chú ý. Theo y văn, nhiều loài Rhododendron khác (như Náo dương hoa, Rhododendron molle) có độc mạnh với tim và thần kinh; Mãn sơn hồng (R. dauricum) và Ánh sơn hồng (R. simsii) là hai vị khác nhau, không dùng thay thế nhau. Chỉ dùng theo liều Dược điển và theo chỉ định thầy thuốc."},
"anh-tuc-xac":{"lv": "doc", "lab": "CHỨA ALKALOID THUỐC PHIỆN, GÂY NGHIỆN", "txt": "Dược điển ghi tính chất có độc, dễ gây nghiện, không nên dùng thường xuyên; phụ nữ có thai và trẻ em cấm dùng; vận động viên thận trọng. Đây là dược liệu thuộc diện kiểm soát đặc biệt, bị cấm hoặc quản lý rất nghiêm theo luật ở Việt Nam và nhiều nước; chỉ dùng theo đơn của thầy thuốc có thẩm quyền, tuyệt đối không tự trồng, mua bán, tàng trữ hay tự dùng."},
"con-bo":{"lv": "luu", "lab": "GIÀU IOD, KIM LOẠI NẶNG", "txt": "Dược điển không ghi mục chú ý nhưng có quy định hàm lượng iod và giới hạn kim loại nặng. Theo y văn, người bệnh tuyến giáp (cường giáp, viêm giáp tự miễn) hoặc đang dùng thuốc tuyến giáp nên hỏi thầy thuốc trước khi dùng nhiều và kéo dài. Hải đới và Côn bố đều là nguồn của vị thuốc này; Hải tảo (Sargassum) là vị khác."},
"hoa-quat-hong":{"lv": "luu", "lab": "HAY BỊ LÀM GIẢ, DỄ NHẦM", "txt": "Dược điển không ghi mục chú ý. Hóa quất hồng thật (từ Hóa Châu bưởi, Citrus grandis ‘Tomentosa’) hay bị trộn lẫn hoặc làm giả bằng vỏ bưởi thường; cũng không nhầm với Trần bì hay Thanh bì (vỏ quýt, Citrus reticulata). Theo y văn, tính ấm khô, người ho khan do âm hư không nên dùng."},
"ai-dia-tra":{"lv": "luu", "lab": "DỄ NHẦM CÂY CÙNG CHI ARDISIA", "txt": "Dược điển không ghi mục chú ý. Cần phân biệt Ải địa trà (Ardisia japonica) với Chu sa căn (Ardisia crenata) và Bách lượng kim (Ardisia crispa), là những vị thuốc riêng; không dùng lẫn."},
"cam-tung":{"lv": "luu", "lab": "NGUỒN HOANG DẠI ĐANG SUY GIẢM", "txt": "Dược điển không ghi mục chú ý. Theo y văn bảo tồn, loài mọc ở vùng cao này bị khai thác quá mức và nằm trong diện bảo vệ; nên mua hàng có nguồn gốc hợp pháp. Theo giáo trình, người khí hư, huyết nhiệt nên thận trọng."},
"dao-dau":{"lv": "luu", "lab": "HẠT SỐNG KHÔNG ĂN ĐƯỢC", "txt": "Dược điển không ghi mục chú ý. Theo y văn về hạt Canavalia, hạt sống hoặc nấu chưa chín kỹ chứa canavanin và lectin có thể gây buồn nôn, đau bụng; chỉ dùng hạt đã bào chế đúng cách. Theo giáo trình, nấc do nhiệt không dùng."},
"sa-la-tu":{"lv": "luu", "lab": "HẠT CÓ SAPONIN KÍCH ỨNG", "txt": "Dược điển không ghi mục chú ý. Theo y văn, hạt các loài Aesculus sống chứa saponin (aescin) có thể kích ứng đường tiêu hóa và gây độc khi ăn nhiều; không ăn hạt chưa bào chế, dùng theo chỉ định thầy thuốc. Không nhầm với hạt dẻ ăn được."},
"dao-nha":{"lv": "luu", "lab": "ĐỪNG NHẦM VỚI CỐC NHA, MẠCH NHA", "txt": "Dược điển không ghi mục chú ý. Đạo nha (mầm thóc lúa), Cốc nha (mầm hạt kê Setaria italica) và Mạch nha (mầm đại mạch) là ba vị khác nhau; tên gọi dễ bị dùng lẫn ở một số vùng."},
"son-tra-diep":{"lv": "luu", "lab": "THUỐC TIM, HUYẾT ÁP; DỄ NHẦM SƠN TRA", "txt": "Dược điển không ghi mục chú ý. Theo y văn, lá sơn tra có thể tác động lên huyết áp và tim mạch; người đang dùng thuốc hạ áp, thuốc tim hoặc thuốc chống đông nên hỏi thầy thuốc. ‘Sơn tra’ ở miền núi Việt Nam thường là Táo mèo (Docynia indica, Malus doumeri), là cây khác với Crataegus."},
"hoe-giac":{"lv": "luu", "lab": "THẬN TRỌNG KHI CÓ THAI, TỲ VỊ HƯ HÀN", "txt": "Dược điển không ghi mục chú ý. Theo giáo trình, tính hàn nên người tỳ vị hư hàn và phụ nữ có thai thận trọng. Không nhầm với các cây cùng chi Sophora như Khổ sâm (Sophora flavescens) hay Sơn đậu căn (Sophora tonkinensis)."},
"tu-chau-diep":{"lv": "luu", "lab": "DỄ NHẦM NHIỀU LOÀI CALLICARPA", "txt": "Dược điển không ghi mục chú ý. Tử châu diệp (Callicarpa formosana) khác Khỏa hoa tử châu (Callicarpa nudiflora, có chuyên luận riêng) và các loài Callicarpa dân gian khác như ‘nàng nàng’; không dùng lẫn. Theo giáo trình, tính mát nên người tỳ vị hư hàn thận trọng."},
"dang-trac-te-tan":{"lv": "luu", "lab": "DỄ NHẦM TÊN: ĐĂNG TRẢN TẾ TÂN ≠ TẾ TÂN", "txt": "Đăng trản tế tân (Erigeron breviscapus, họ Cúc) hoàn toàn khác Tế tân (Asarum, họ Mã đậu linh); không dùng lẫn. Chưa đối chiếu được mục chú ý của Dược điển. Theo y văn, người đang dùng thuốc chống đông, chống ngưng tập tiểu cầu, có xu hướng chảy máu hoặc có thai cần hỏi thầy thuốc khi dùng thuốc hoạt huyết."},
"ke-quan-hoa":{"lv": "luu", "lab": "THU SÁP: KHÔNG DÙNG KHI TÀ CHƯA HẾT", "txt": "Dược điển không ghi mục chú ý. Theo nguyên tắc dùng thuốc thu sáp trong giáo trình, khi lỵ cấp tính hoặc khí hư do nhiệt thấp chưa hết thì không nên dùng sớm. Không nhầm với Thanh tương tử (hạt Celosia argentea), là vị khác."},
"tam-lang":{"lv": "manh", "lab": "CẤM DÙNG KHI CÓ THAI; KỴ MANG TIÊU", "txt": "Dược điển ghi: phụ nữ có thai cấm dùng; không dùng chung với Mang tiêu (芒硝) và Huyền minh phấn (玄明粉). Đây là thuốc phá huyết mạnh. Không nhầm Hắc tam lăng với Kinh tam lăng (Scirpus yagara, họ Cói) từng dùng ở một số vùng."},
"luu-ky-no":{"lv": "luu", "lab": "DỄ NHẦM LOÀI; THẬN TRỌNG KHI CÓ THAI", "txt": "Chưa đối chiếu được mục chú ý của Dược điển. Tên ‘Lưu ký nô’ dùng cho nhiều loài khác nhau (Nam lưu ký nô là Artemisia anomala; Bắc lưu ký nô là Siphonostegia chinensis) nên cần xác định đúng loài. Theo giáo trình, thuốc phá huyết thông kinh nên phụ nữ có thai thận trọng."},
"phien-khuong-hoang":{"lv": "luu", "lab": "THẬN TRỌNG KHI CÓ THAI", "txt": "Dược điển ghi: phụ nữ có thai thận trọng khi dùng. Phiến khương hoàng (thân rễ Curcuma wenyujin) khác Khương hoàng (Curcuma longa, củ nghệ), Uất kim và Nga truật; không dùng lẫn."},
"phong-huong-chi":{"lv": "luu", "lab": "NHỰA THƠM: DỄ DỊ ỨNG; ĐỪNG NHẦM TÔ HỢP HƯƠNG", "txt": "Dược điển không ghi mục chú ý. Phong hương chi (nhựa Liquidambar formosana) khác Tô hợp hương (Liquidambar orientalis). Theo y văn, phụ nữ có thai thận trọng với thuốc hoạt huyết; người dị ứng nhựa thơm nên thử trên da nhỏ trước khi dùng ngoài."},
"minh-dang-sam":{"lv": "luu", "lab": "KHÔNG PHẢI ĐẲNG SÂM, SA SÂM", "txt": "Dược điển không ghi cảnh báo riêng. Minh đảng sâm (Changium smyrnioides, họ Hoa tán) khác hẳn Đảng sâm (Codonopsis) và Sa sâm; tên gọi địa phương dễ gây lẫn. Theo giáo trình, tính hơi lạnh nên người tỳ vị hư hàn, tiêu chảy cần thận trọng. Theo y văn, từng có hàng trộn lẫn hoặc giả từ rễ cây khác, nên mua nơi tin cậy."},
"hong-sam":{"lv": "luu", "lab": "KỴ LÊ LÔ, NGŨ LINH CHI", "txt": "Dược điển ghi: không dùng chung với Lê lô (藜蘆) và Ngũ linh chi (五靈脂). Theo y văn, hồng sâm tính ấm, người âm hư hỏa vượng, sốt do thực nhiệt, huyết áp cao chưa kiểm soát cần hỏi thầy thuốc trước khi dùng. Dược điển dặn sắc riêng (3–9 g) rồi hòa vào thuốc, không dùng tùy tiện như thực phẩm."},
"do-trong-diep":{"lv": "luu", "lab": "LIỀU KHÁC VỎ ĐỖ TRỌNG", "txt": "Dược điển không ghi cảnh báo riêng. Lá và vỏ Đỗ trọng là hai vị thuốc riêng trong Dược điển với liều khác nhau (lá 10–15 g, vỏ 6–10 g), không tự thay nhau theo cùng một liều. Theo giáo trình, người âm hư hỏa vượng nên thận trọng; người đang dùng thuốc hạ áp nên hỏi thầy thuốc vì thực nghiệm lá có tác dụng hạ áp."},
"thiet-bi-thach-hoc":{"lv": "luu", "lab": "HÀNG GIẢ PHỔ BIẾN, CHƯA ĐỐI CHIẾU DƯỢC ĐIỂN", "txt": "Chưa đối chiếu Dược điển cho vị này. Theo y văn, Thiết bì thạch hộc đắt tiền nên hàng giả và hàng pha loại thạch hộc rẻ rất phổ biến, nhất là dạng ‘phong đẩu’ đã uốn xoắn khó kiểm tra bằng mắt. Theo giáo trình, tính hơi lạnh nhờn nên người tỳ vị hư hàn, đầy bụng, rêu lưỡi dày nhớt, mới cảm cần thận trọng."},
"thuc-dia-hoang":{"lv": "luu", "lab": "NHỜN DÍNH, DỄ TRỆ TỲ", "txt": "Dược điển không ghi cảnh báo riêng. Theo giáo trình, thục địa nhờn dính, người tỳ vị hư yếu, đầy bụng, đại tiện lỏng, đờm nhiều khí trệ nên thận trọng; thường được phối vị hành khí (Sa nhân, Trần bì). Không nhầm với Sinh địa hoàng (tính lạnh, thanh nhiệt lương huyết) vì tác dụng khác nhau."},
"son-mach-mon-dong":{"lv": "luu", "lab": "KHÔNG ĐỒNG NHẤT MẠCH MÔN ĐÔNG", "txt": "Dược điển không ghi cảnh báo riêng và liệt Sơn mạch đông (Liriope) riêng với Mạch môn đông (Ophiopogon japonicus); khi mua cần hỏi rõ nguồn gốc, không mặc định là một. Theo giáo trình, tính lạnh nhuận nên người tỳ vị hư hàn, tiêu chảy, mới cảm phong hàn ho không nên dùng."},
"xuan-bi":{"lv": "luu", "lab": "ĐỪNG NHẦM XÚ XUÂN VỚI HƯƠNG XUÂN", "txt": "Dược điển không ghi cảnh báo riêng. Xuân bì là vỏ cây Xú xuân (Ailanthus altissima, họ Thanh thất), khác hẳn vỏ Hương xuân (Toona sinensis, họ Xoan) có lá non ăn được; không dùng thay nhau. Theo giáo trình, tính lạnh, người tỳ vị hư hàn không dùng. Thực nghiệm cho thấy các quassinoid trong cây có độc tính trên tế bào, nên không tự dùng liều cao hoặc kéo dài."},
"to-hop-huong":{"lv": "luu", "lab": "CHỈ DÙNG CHỨNG BẾ, KHÔNG DÙNG CHỨNG THOÁT", "txt": "Dược điển không ghi mục chú ý riêng. Theo giáo trình, thuốc thơm tán mạnh chỉ dùng cho chứng bế (hôn mê cấp, thể thực hàn), không dùng cho chứng thoát (mồ hôi lạnh, tay chân lạnh, mạch yếu) hay âm hư hỏa vượng. Theo y văn, người có thai nên tránh các hoàn tán thơm xuyên mạnh. Không nhầm với Phong hương chỉ và An tức hương; hàng thật hiếm, nhựa nhân tạo và nhựa pha trộn khá phổ biến."},
"an-tuc-huong":{"lv": "luu", "lab": "THUỐC THƠM; DỄ NHẦM NHỰA KHÁC", "txt": "Dược điển không ghi mục chú ý. Theo giáo trình, thuốc thơm hao khí, người âm hư hỏa vượng, khí hư cần thận trọng. Nhựa benzoin có thể gây dị ứng da hoặc kích ứng khi dùng ngoài. Không nhầm với benzoin Sumatra (từ loài Styrax khác), Tô hợp hương hay Phong hương chỉ."},
"lien-phong":{"lv": "luu", "lab": "DƯỢC ĐIỂN CHỈ GHI DẠNG THAN", "txt": "Dược điển chỉ ghi dạng thuốc thái phiến là Liên phòng thán (gương sen sao than), không ghi gương sen sống. Theo giáo trình, thuốc cầm máu thu sáp, người đang nhiệt thịnh hoặc ứ huyết chưa tan nên thận trọng. Chảy máu nhiều hoặc kéo dài (băng huyết, tiểu ra máu, đi ngoài ra máu) cần đi khám, không tự cầm máu bằng thuốc."},
"tung-hoa-phan":{"lv": "luu", "lab": "DƯỢC ĐIỂN CHỈ GHI DÙNG NGOÀI; DỄ DỊ ỨNG PHẤN HOA", "txt": "Dược điển chỉ ghi dùng ngoài (rắc đắp), không ghi đường uống. Theo y văn, phấn hoa là chất gây dị ứng thường gặp; người có tiền sử dị ứng phấn hoa, hen, viêm mũi dị ứng cần thận trọng và ngưng ngay khi nổi mẩn, ngứa, khó thở. Các sản phẩm phấn hoa thông ‘phá vách tế bào’ bán dưới dạng thực phẩm chức năng có công dụng quảng cáo thường vượt chứng cứ khoa học."},
"nam-ngu-vi-tu":{"lv": "luu", "lab": "KHÁC NGŨ VỊ TỬ BẮC", "txt": "Dược điển liệt riêng Ngũ vị tử (Bắc, Schisandra chinensis) và Nam ngũ vị tử (Schisandra sphenanthera) với chỉ thị khác nhau (schisandrin ở Bắc, schisantherin A ở Nam); không coi là một khi mua. Dược điển không ghi cảnh báo riêng. Theo giáo trình, vị chua thu liễm nên người còn ngoại tà (mới cảm), ho mới phát hoặc trong có thực nhiệt cần thận trọng."},
"du-cam-tu":{"lv": "luu", "lab": "KHÁC DIỆP HẠ CHÂU; TÍNH MÁT", "txt": "Dược điển ghi đây là dược liệu của dân tộc Tạng và không ghi cảnh báo riêng. Dư cam tử (Phyllanthus emblica, Chùm ruột núi) cùng chi nhưng khác hẳn Diệp hạ châu (Phyllanthus urinaria); không dùng thay nhau. Theo y văn, tính mát, người tỳ vị hư hàn, đại tiện lỏng nên thận trọng."},
"mao-kha-tu":{"lv": "luu", "lab": "KHÔNG NHẦM VỚI KHA TỬ", "txt": "Dược điển ghi đây là dược liệu của dân tộc Tạng, không ghi cảnh báo riêng. Mao kha tử (Terminalia bellirica) khác Kha tử (Terminalia chebula), cùng nằm trong ‘Tam quả’ nhưng là hai vị riêng. Theo giáo trình, vị chát thu liễm nên người đại tiện táo kết cần thận trọng; nên dùng theo chỉ dẫn của thầy thuốc quen y học Tạng."},
"sa-cuc":{"lv": "luu", "lab": "THẬN TRỌNG KHI DÙNG CHỐNG ĐÔNG", "txt": "Dược điển ghi đây là dược liệu của dân tộc Mông Cổ và Tạng, không ghi cảnh báo riêng. Theo y văn, quả vị chua, người đau dạ dày nhiều axit nên dùng thận trọng; người đang dùng thuốc chống đông hoặc kháng kết tập tiểu cầu nên hỏi thầy thuốc vì thực nghiệm cho thấy quả có thể ảnh hưởng đông máu. Không nhầm với nước ép, dầu sa cức làm thực phẩm."},
"ngan-hanh-diep":{"lv": "manh", "lab": "NGUY CƠ CHẢY MÁU, DỊ ỨNG", "txt": "Dược điển ghi: có thực tà thì kiêng dùng (有實邪者忌用). Theo y văn, chiết xuất lá có thể làm tăng nguy cơ chảy máu, cần hỏi thầy thuốc khi dùng cùng warfarin, thuốc kháng kết tập tiểu cầu hoặc trước phẫu thuật; còn có thể gây đau đầu, rối loạn tiêu hóa, dị ứng da (axit ginkgolic). Nên dùng sản phẩm chuẩn hóa, không tự phơi lá dùng lâu dài. Không nhầm với hạt Bạch quả (白果), vị thuốc khác có độc khi dùng quá liều."},
"cau-cot-diep":{"lv": "luu", "lab": "KHÔNG ĐỒNG NHẤT KHỔ ĐINH TRÀ", "txt": "Dược điển không ghi cảnh báo riêng. Tên thương mại ‘Khổ đinh trà’ được dùng cho lá nhiều loài Ilex khác nhau, không đồng nhất với Cẩu cốt diệp (Ilex cornuta) của Dược điển. Theo giáo trình, tính mát nên người tỳ vị hư hàn, tiêu chảy cần thận trọng; không tự uống thay trà kéo dài."},
"xa-sang-tu":{"lv": "doc", "lab": "CÓ ĐỘC NHẸ (小毒)", "txt": "Dược điển ghi tính vị ‘cay, đắng, ấm; có độc nhẹ (小毒)’ và liều 3–10 g/ngày, dùng ngoài vừa đủ. Không vượt liều Dược điển. Theo y văn, tính ấm táo, người âm hư hỏa vượng, thấp nhiệt vùng hạ tiêu nên thận trọng; phụ nữ có thai nên tránh. Dùng ngoài có thể gây kích ứng da, niêm mạc; không thay thế điều trị bệnh phụ khoa, da liễu."},
"thuy-hong-hoa-tu":{"lv": "luu", "lab": "PHÁ HUYẾT MẠNH; THAI KỲ TRÁNH", "txt": "Dược điển không ghi cảnh báo riêng. Theo giáo trình, đây là thuốc phá huyết tiêu tích mạnh, phụ nữ có thai và người không có huyết ứ trệ, tỳ vị hư hàn nên tránh. Liều Dược điển khá cao (15–30 g) nên chỉ dùng theo chỉ dẫn thầy thuốc. Khối cứng trong bụng cần được thăm khám loại trừ bệnh lý nặng."},
"du-tri-tu":{"lv": "luu", "lab": "ĐỪNG NHẦM VỚI QUAN MỘC THÔNG", "txt": "Dược điển không ghi cảnh báo riêng. Dự tri tử là quả của cây Akebia (họ Mộc thông) nhưng tên ‘mộc thông’ từng bị dùng lẫn với Quan mộc thông (Aristolochia manshuriensis) chứa axit aristolochic gây hại thận, nhiều nước đã cấm; hai loại khác hẳn nhau. Theo giáo trình, tính lạnh nên người tỳ vị hư hàn và phụ nữ có thai cần thận trọng."},
"moc-biet-tu":{"lv": "doc", "lab": "ĐỘC (有毒) · THẬN TRỌNG KHI CÓ THAI", "txt": "Dược điển ghi tính vị ‘có độc’ (有毒) và 孕妇慎用 (thận trọng khi có thai); liều 0,9–1,2 g, dùng ngoài tán bột trộn dầu hoặc giấm. Hạt chứa protein và saponin độc; không tự ý uống. Phần màng đỏ của quả gấc ăn được là phần khác với hạt (vị thuốc)."},
"tho-kinh-bi":{"lv": "doc", "lab": "ĐỘC (有毒) · CHỈ GHI DÙNG NGOÀI", "txt": "Dược điển ghi tính vị ‘có độc’ (有毒) và chỉ nêu cách dùng ngoài (ngâm giấm hoặc rượu bôi xát, hoặc tán bột trộn bôi chỗ bệnh); không ghi liều uống. Theo y văn có thể gây kích ứng da; không bôi lên da vỡ rộng hoặc niêm mạc."},
"dang-hoang":{"lv": "doc", "lab": "ĐỘC MẠNH · CHỈ DÙNG NGOÀI · CHƯA ĐỐI CHIẾU DƯỢC ĐIỂN", "txt": "Gôm nhựa vàng có độc mạnh theo y văn: uống có thể gây nôn, đau bụng, tiêu chảy, tổn thương gan thận. Dược điển 2020 không có chuyên luận để đối chiếu; không đưa liều tự dùng, không bôi lên vết thương hở rộng, thận trọng khi có thai."},
"hong-dai-kich":{"lv": "manh", "lab": "TRỤC THỦY MẠNH · CÓ ĐỘC NHẸ (THEO Y VĂN)", "txt": "Chưa đối chiếu Dược điển 2020. Theo y văn và giáo trình: vị thuốc trục thủy mạnh, có độc nhẹ, phụ nữ có thai không dùng, kiêng dùng chung Cam thảo. Không đưa liều tự dùng; chỉ dùng cùng thầy thuốc. Không nhầm với Kinh đại kích (Euphorbia pekinensis, họ Đại kích)."},
"thien-tien-tu":{"lv": "doc", "lab": "ĐỘC MẠNH (大毒) · CẤM TIM, GLÔCÔM, CÓ THAI", "txt": "Dược điển ghi tính vị ‘độc mạnh’ (有大毒), liều 0,06–0,6 g, và 心脏病、心动过速、青光眼患者及孕妇禁用 (cấm dùng cho người bệnh tim, nhịp tim nhanh, glôcôm và phụ nữ có thai). Hạt chứa alcaloid tropan (hyoscyamin, scopolamin); ngộ độc gây khô miệng, đồng tử giãn, mạch nhanh, kích động, ảo giác. Không tự dùng."},
"hoa-son-sam":{"lv": "doc", "lab": "ĐỘC (有毒) · CẤM GLÔCÔM · KHÔNG DÙNG NHIỀU", "txt": "Dược điển ghi tính vị ‘có độc’ (有毒), liều 0,1–0,2 g, và 不宜多服，以免中毒；青光眼患者禁服；孕妇及前列腺重度肥大者慎用 (không dùng nhiều để tránh ngộ độc; cấm cho người bệnh glôcôm; thận trọng với phụ nữ có thai và người phì đại tuyến tiền liệt nặng). Chứa alcaloid tropan. Không nhầm với Nhân sâm."},
"dai-tao-giac":{"lv": "doc", "lab": "ĐỘC NHẸ (小毒) · CÓ THAI, HO RA MÁU", "txt": "Dược điển ghi tính vị ‘có độc nhẹ’ (有小毒), liều 1–1,5 g (thường vào hoàn tán), và 孕妇及咯血、吐血患者忌服 (phụ nữ có thai và người ho ra máu, nôn ra máu không dùng). Saponin kích ứng niêm mạc. Không nhầm với Trư nha tạo (quả dị dạng không hạt, mục riêng) hoặc bồ kết gội đầu ở Việt Nam (thường là Gleditsia fera)."},
"tru-nha-tao":{"lv": "doc", "lab": "ĐỘC NHẸ (小毒) · CÓ THAI, HO RA MÁU", "txt": "Dược điển ghi tính vị ‘có độc nhẹ’ (有小毒), liều 1–1,5 g (thường vào hoàn tán), và 孕妇及咯血、吐血患者禁用 (phụ nữ có thai và người ho ra máu, nôn ra máu cấm dùng). Saponin kích ứng niêm mạc; dùng ngoài thổi mũi chỉ do thầy thuốc hướng dẫn."},
"loi-hoan":{"lv": "luu", "lab": "KHÔNG SẮC · KHÔNG ĐUN NÓNG", "txt": "Dược điển ghi không nên cho vào thuốc sắc, không được hấp nấu hoặc sấy nhiệt cao (hoạt chất là protease nhạy nhiệt); dùng bột uống với nước ấm sau bữa ăn, 15–21 g mỗi ngày chia 3 lần, 3 ngày. Dược điển 2020 không gắn nhãn độc và không có mục chú ý; một số sách cổ ghi độc nhẹ, nên không dùng khi không có giun sán (theo y văn). Hạch có mặt cắt nâu hóa sừng không dùng làm thuốc."},
"hac-sat":{"lv": "doc", "lab": "ĐỘC NHẸ (小毒) · KHÔNG QUÁ LIỀU", "txt": "Dược điển ghi tính vị ‘có độc nhẹ’ (有小毒), liều 3–9 g; không có mục chú ý. Theo y văn: quá liều có thể gây chóng mặt, buồn nôn, đau bụng; thận trọng với trẻ em, phụ nữ có thai, người tỳ vị hư yếu. Không nhầm với ‘Nam hạc sắt’ (quả Daucus carota)."},
"lien-tien-thao":{"lv": "luu", "lab": "DỄ NHẦM VỚI KIM TIỀN THẢO", "txt": "Dược điển không ghi mục chú ý. Liên tiền thảo (Hoạt huyết đan, Glechoma longituba) hay bị gọi nhầm là ‘Kim tiền thảo’; Kim tiền thảo ở Trung Quốc là Lysimachia christinae còn ở Việt Nam thường là Desmodium styracifolium. Khi mua cần hỏi rõ tên khoa học."},
"thanh-diep-dam":{"lv": "luu", "lab": "THẬN TRỌNG NGƯỜI HƯ HÀN", "txt": "Dược điển ghi 虚寒者慎服 (thận trọng với người hư hàn). Vị đắng lạnh; tỳ vị hư lạnh, tiêu chảy, ăn kém không nên dùng nhiều. Chi Swertia có nhiều loài hình thái giống nhau, cần mua đúng nguồn Swertia mileensis."},
"thach-dieu-lan":{"lv": "luu", "lab": "DỄ NHẦM TÊN CÂY CẢNH, THẠCH HỘC", "txt": "Dược điển không ghi mục chú ý. Thạch điếu lan (Lysionotus pauciflorus, họ Khổ cự đài) dễ nhầm với ‘điếu lan’ (cây cảnh Chlorophytum) và Thạch hộc (Dendrobium) vì tên gần giống; cần mua đúng nguồn."},
"nhat-chi-hoang-hoa":{"lv": "luu", "lab": "NHẦM LOÀI XÂM LẤN", "txt": "Dược điển không ghi mục chú ý. Dược điển chỉ nhận Solidago decurrens; ‘Nhất chi hoàng hoa Canada’ (Solidago canadensis) là loài xâm lấn nhập từ Bắc Mỹ, không phải nguồn dược liệu của Dược điển. Theo y văn tính mát, người tỳ vị hư lạnh nên thận trọng."},
"nga-bat-thuc-thao":{"lv": "luu", "lab": "KÍCH ỨNG KHI HÍT HOẶC ĐẮP NGOÀI", "txt": "Dược điển không ghi mục chú ý. Theo y văn: vị cay thơm, hít bột hoặc đắp tươi có thể kích ứng niêm mạc mũi và da; người dị ứng với họ Cúc nên thận trọng. Cần mua đúng loài Centipeda minima."},
"can-cot-thao":{"lv": "luu", "lab": "NHẦM VỚI HẠ KHÔ THẢO · TÍNH LẠNH", "txt": "Dược điển không ghi mục chú ý. Theo y văn: tính lạnh, người tỳ vị hư hàn, tiêu chảy nên thận trọng. ‘Bạch mao hạ khô thảo’ (Ajuga decumbens) khác Hạ khô thảo (Prunella vulgaris) dù hay bị gọi chung là ‘hạ khô thảo’."},
"kim-phat-thao":{"lv": "luu", "lab": "KHÁC TOÀN PHÚC HOA · NGƯỜI ÂM HƯ", "txt": "Dược điển không ghi mục chú ý. Kim phất thảo là phần thân lá, khác vị Toàn phúc hoa (phần hoa) dù cùng loài. Theo giáo trình: thuốc giáng khí tiêu đờm tính ấm tán, người ho khan do âm hư, tỳ vị hư lạnh tiêu chảy nên thận trọng."},
"ngoa-tung":{"lv": "luu", "lab": "TÍNH CHUA LẠNH · DỄ NHẦM THUỐC BỎNG", "txt": "Dược điển không ghi mục chú ý. Theo y văn: tính chua lạnh, người tỳ vị hư lạnh, phụ nữ có thai nên hỏi thầy thuốc; không dùng liều cao kéo dài. Không nhầm Ngõa tùng (Orostachys) với Thuốc bỏng (Kalanchoe pinnata), cùng họ Crassulaceae nhưng khác chi."},
"bach-khuat-thai":{"lv": "doc", "lab": "ĐỘC (有毒) · NHỰA KÍCH ỨNG, CÓ BÁO CÁO HẠI GAN", "txt": "Dược điển ghi tính vị ‘có độc’ (有毒), liều 9–18 g; không có mục chú ý riêng. Chứa nhiều alcaloid isoquinolin (chelerythrin, chelidonin, sanguinarin…). Theo y văn: nhựa tươi kích ứng da; có báo cáo tổn thương gan ở người dùng chế phẩm uống; tránh khi bệnh gan hoặc có thai. Không tự bôi hay uống cây tươi."},
"moc-mien-hoa":{"lv": "luu", "lab": "DỄ NHẦM VỚI BÔNG GÒN, TÍNH MÁT", "txt": "Dược điển không ghi mục chú ý. Mộc miên (cây gạo, Bombax ceiba) dễ nhầm với bông gòn (Ceiba pentandra) và ‘mộc miên’ chỉ cây bông (Gossypium). Theo giáo trình: tính mát, người tỳ vị hư lạnh, tiêu chảy do lạnh nên thận trọng."},
"nhan-sam-diep":{"lv": "luu", "lab": "KỴ LÊ LÔ, NGŨ LINH CHI", "txt": "Dược điển ghi không nên dùng chung với Lê lô và Ngũ linh chi. Tính lạnh, người tỳ vị hư hàn nên thận trọng."},
"che-ha-thu-o":{"lv": "manh", "lab": "NGUY CƠ TỔN THƯƠNG GAN", "txt": "Có nhiều báo cáo tổn thương gan liên quan đến Hà thủ ô và chế phẩm. Chỉ dùng đúng liều, thời gian ngắn; ngừng thuốc và đi khám khi vàng da, nước tiểu sẫm, mệt, chán ăn. Người bệnh gan, có thai, cho con bú nên hỏi thầy thuốc."},
"phan-cat":{"lv": "luu", "lab": "DỄ NHẦM VỚI CÁT CĂN", "txt": "Dược điển không ghi cảnh báo riêng. Phấn cát (Pueraria thomsonii) và Cát căn (Pueraria lobata) là hai mục riêng trong Dược điển với tiêu chuẩn khác nhau. Dược liệu có thể xông lưu huỳnh; Dược điển quy định dư lượng SO2 không quá 400 mg/kg. Theo y văn, người tỳ vị hư hàn nên thận trọng."},
"dai-dau-hoang-quyen":{"lv": "luu", "lab": "DỊ ỨNG ĐẬU NÀNH", "txt": "Dược điển không ghi cảnh báo riêng. Dược liệu làm từ đậu nành nảy mầm: người dị ứng đậu nành không dùng; chứa isoflavone nên người có bệnh phụ thuộc estrogen cần hỏi thầy thuốc."},
"dong-lang-thao":{"lv": "luu", "lab": "KHÔNG THAY THUỐC ĐIỀU TRỊ UNG THƯ", "txt": "Dược điển không ghi mục chú ý. Đông lăng thảo (oridonin) mới có dữ liệu thực nghiệm, chứng cứ lâm sàng ở người còn hạn chế; người bệnh ung thư không tự thay thuốc điều trị chính. Theo giáo trình, người tỳ vị hư hàn, đi lỏng nên thận trọng. Không nhầm với Đông trùng hạ thảo hay Đông quỳ quả."},
"nam-ban-lam-can":{"lv": "luu", "lab": "DỄ NHẦM VỚI BẢN LAM CĂN", "txt": "Nam bản lam căn (rễ Baphicacanthus cusia, họ Ô rô) khác Bản lam căn (rễ Isatis indigotica, họ Cải); Dược điển có hai chuyên luận riêng. Dược điển không ghi mục chú ý; theo giáo trình, tính lạnh đắng, tỳ vị hư hàn không nên dùng lâu."},
"uy-lang-thai":{"lv": "luu", "lab": "DỄ NHẦM VỚI BẠCH ĐẦU ÔNG", "txt": "Một số vùng gọi nhầm Ủy lăng thái là Bạch đầu ông (rễ Pulsatilla chinensis, họ Mao lương), hai vị khác hẳn nhau; cũng không nhầm với Phiên bạch thảo. Dược điển không ghi mục chú ý."},
"cuu-tat-ung":{"lv": "luu", "lab": "VỊ ĐẮNG LẠNH, DỄ NHẦM LOÀI ILEX", "txt": "Dược điển không ghi mục chú ý. Dùng vỏ cây Ilex rotunda; đừng nhầm với lá Tứ quý thanh (Ilex chinensis) hay rễ Mao đông thanh (Ilex pubescens). Theo giáo trình, tính lạnh đắng, tỳ vị hư hàn nên thận trọng."},
"kho-dia-dinh":{"lv": "luu", "lab": "DỄ NHẦM VỚI TỬ HOA ĐỊA ĐINH", "txt": "Khổ địa đinh (Corydalis bungeana, họ Anh túc, chứa alkaloid) khác Tử hoa địa đinh (Viola yedoensis, họ Hoa tím); không dùng lẫn. Dược điển không ghi mục chú ý; theo giáo trình, tính lạnh đắng, tỳ vị hư hàn không nên dùng, dùng đúng liều."},
"cam-dang-lung":{"lv": "luu", "lab": "PHỤ NỮ CÓ THAI THẬN TRỌNG (THEO Y VĂN)", "txt": "Dược điển không ghi mục chú ý. Theo y văn cổ truyền, phụ nữ có thai và người tỳ hư đi lỏng nên thận trọng hoặc tránh dùng. Không nhầm với tầm bóp (Physalis angulata) hay thù lù (Physalis peruviana)."},
"cam-toai":{"lv": "doc", "lab": "TRỤC THỦY MẠNH, CẤM CHO NGƯỜI CÓ THAI", "txt": "Dược điển Trung Quốc 2020 ghi Cam toại vị đắng, tính lạnh, có độc; liều 0,5–1,5 g, phụ nữ có thai cấm dùng, không dùng chung với Cam thảo. Có thể gây nôn, đau bụng, tiêu chảy dữ dội, mất nước. Chỉ dùng khi có chỉ định và theo dõi của thầy thuốc. Nhựa mủ kích ứng da và mắt."},
"xuyen-moc-thong":{"lv": "luu", "lab": "PHÂN BIỆT VỚI QUAN MỘC THÔNG", "txt": "Xuyên mộc thông (Clematis) không phải Quan mộc thông (Aristolochia manshuriensis, chứa axit aristolochic gây độc thận, đã bị loại khỏi Dược điển). Chỉ dùng loại đúng loài, mua nơi tin cậy; dùng đúng liều Dược điển 3–6 g/ngày."},
"hoang-thuc-quy-hoa":{"lv": "luu", "lab": "PHỤ NỮ CÓ THAI THẬN TRỌNG", "txt": "Dược điển ghi mục 禁忌: phụ nữ có thai thận trọng khi dùng. Tính lạnh, người tỳ vị hư hàn hay đi lỏng cần thận trọng."},
"huong-gia-bi":{"lv": "doc", "lab": "THUỐC CÓ ĐỘC THEO DƯỢC ĐIỂN (有毒)", "txt": "Dược điển ghi tính vị có độc (有毒) và mục 注意: không nên dùng quá liều. Vỏ rễ chứa glycoside tim (periplocin…), quá liều có thể gây buồn nôn, nôn, nhịp tim chậm hoặc loạn nhịp. Không dùng thay Ngũ gia bì (Acanthopanax) vì đã có ngộ độc do nhầm lẫn; người có bệnh tim, đang dùng thuốc tim, phụ nữ có thai và trẻ em cần hỏi thầy thuốc. Không vượt liều Dược điển 3–6 g/ngày."},
"ot-cay":{"lv": "luu", "lab": "KÍCH ỨNG, CAY NÓNG", "txt": "Dược điển không ghi độc, nhưng ớt cay nóng, gây rát niêm mạc và dạ dày; tuyệt đối không dính vào mắt, vết thương hở. Người viêm loét dạ dày, trĩ, âm hư hỏa vượng nên kiêng. Không dùng quá liều Dược điển (0,9–2,4 g)."},
"phao-khuong":{"lv": "luu", "lab": "TÍNH NÓNG, CHỈ DÙNG KHI HƯ HÀN", "txt": "Tính cay nóng; chỉ hợp chảy máu do hư hàn. Chảy máu do nhiệt, âm hư nội nhiệt không dùng; phụ nữ có thai thận trọng. Không quá 3–9 g/ngày theo Dược điển."},
"ha-thien-vo":{"lv": "luu", "lab": "CHỨA ALKALOID: HỎI THẦY THUỐC", "txt": "Dược điển không ghi mục chú ý cho vị này. Củ chứa alkaloid isoquinolin nên không tự ý dùng quá liều Dược điển (6–12 g). Theo y văn, phụ nữ có thai và người đang dùng thuốc an thần hoặc chống đông nên hỏi thầy thuốc trước khi dùng. Không nhầm với Diên hồ sách."},
"can-tat":{"lv": "doc", "lab": "DƯỢC ĐIỂN GHI: CÓ ĐỘC (有毒) - CẤM NGƯỜI DỊ ỨNG SƠN", "txt": "Dược điển ghi: cay, ấm; có độc (有毒). Phụ nữ có thai và người dị ứng với sơn cấm dùng. Nhựa sơn chứa urushiol, có thể gây viêm da tiếp xúc nặng và kích ứng tiêu hóa. Chỉ dùng loại đã chế thành than, đúng liều Dược điển (2–5 g), theo chỉ định thầy thuốc."},
"cap-tinh-tu":{"lv": "doc", "lab": "DƯỢC ĐIỂN GHI: ĐỘC NHẸ (小毒)", "txt": "Dược điển ghi: ấm, có độc nhẹ (小毒). Phụ nữ có thai thận trọng khi dùng. Là thuốc phá huyết mạnh, không dùng quá liều Dược điển (3–5 g) và không dùng kéo dài."},
"doan-huyet-luu":{"lv": "luu", "lab": "CHẢY MÁU KÉO DÀI CẦN KHÁM", "txt": "Dược điển không ghi mục chú ý. Chỉ là thuốc cầm máu hỗ trợ; chảy máu nhiều, kéo dài hoặc không rõ nguyên nhân cần đi khám tìm nguyên nhân, không trì hoãn cấp cứu bằng thuốc thảo dược."},
"xung-uy-tu":{"lv": "luu", "lab": "THẬN TRỌNG: ĐỒNG TỬ GIÃN TO", "txt": "Dược điển ghi: người đồng tử giãn to (瞳孔散大) thận trọng khi dùng. Theo y văn, là thuốc hoạt huyết nên phụ nữ có thai cũng cần thận trọng và hỏi thầy thuốc."},
"binh-boi-mau":{"lv": "luu", "lab": "KỴ VỚI NHÓM Ô ĐẦU", "txt": "Dược điển ghi: không nên dùng cùng Xuyên ô, Chế xuyên ô, Thảo ô, Chế thảo ô, Phụ tử. Tính hơi lạnh, người ho do hàn hoặc tỳ vị hư hàn nên thận trọng; chỉ dùng theo hướng dẫn của thầy thuốc."},
"y-boi-mau":{"lv": "luu", "lab": "KỴ VỚI NHÓM Ô ĐẦU", "txt": "Dược điển ghi: không nên dùng cùng Xuyên ô, Chế xuyên ô, Thảo ô, Chế thảo ô, Phụ tử. Tính hơi lạnh, người ho do hàn hoặc tỳ vị hư hàn nên thận trọng."},
"ho-bac-boi-mau":{"lv": "luu", "lab": "KỴ VỚI NHÓM Ô ĐẦU", "txt": "Dược điển ghi: không nên dùng cùng Xuyên ô, Chế xuyên ô, Thảo ô, Chế thảo ô, Phụ tử. Hàm lượng alkaloid steroid đáng kể, không tự dùng liều cao hay kéo dài."},
"mau-kinh-diep":{"lv": "luu", "lab": "CHỈ DÙNG TƯƠI, KHÔNG NÊU LIỀU", "txt": "Dược điển chỉ ghi dùng lá tươi để cất dầu Mẫu kinh và không nêu liều số. Không tự cất hay uống dầu cô đặc; phụ nữ có thai, trẻ nhỏ nên hỏi thầy thuốc."},
"quat-hong":{"lv": "luu", "lab": "TÍNH ẤM, CAY ĐẮNG", "txt": "Dược điển không ghi chú ý. Theo giáo trình, người ho khan do âm hư, đờm ít dính nên thận trọng; không vượt liều 3–10 g/ngày."},
"dinh-cong-dang":{"lv": "doc", "lab": "ĐỘC NHẸ (小毒) – PHÁT HÃN MẠNH", "txt": "Dược điển ghi có độc nhẹ, có tác dụng phát hãn mạnh. Người hư nhược thận trọng; phụ nữ có thai cấm dùng. Chỉ dùng pha rượu thuốc hoặc xoa ngoài theo chỉ định, không vượt 3–6 g."},
"thien-son-tuyet-lien":{"lv": "luu", "lab": "PHỤ NỮ CÓ THAI KIÊNG DÙNG", "txt": "Dược điển ghi phụ nữ có thai kiêng dùng. Tính ấm nóng, người âm hư hỏa vượng nên thận trọng. Đây là loài quý hiếm cần bảo vệ, dễ bị làm giả bằng các loài ‘tuyết liên’ khác."},
"hoc-ky-sinh":{"lv": "luu", "lab": "KHÔNG ĂN TƯƠI; TỰ HÁI DỄ NHẦM", "txt": "Theo y văn, quả và lá tươi của chi Viscum có thể gây rối loạn tiêu hóa, tim mạch; chỉ dùng dược liệu đã chế biến, đúng loài và đúng liều 9–15 g. Không tự hái tầm gửi trong tự nhiên vì khó phân biệt loài và cây chủ."},
"kim-thiet-toa":{"lv": "doc", "lab": "ĐỘC NHẸ (小毒) – LIỀU RẤT NHỎ", "txt": "Dược điển ghi có độc nhẹ; liều chỉ 0,1–0,3 g, thường dùng trong hoàn tán. Phụ nữ có thai thận trọng. Vị tê, kích ứng họng; người dạ dày yếu hoặc dị ứng cần thận trọng."},
"tang-xuong-bo":{"lv": "luu", "lab": "THẬN TRỌNG LIỀU CAO, DÙNG LÂU", "txt": "Một số chủng Acorus calamus giàu β-asarone, chất bị nghi ngờ gây độc gen và ung thư trên thực nghiệm. Không tự dùng liều cao hoặc kéo dài; phụ nữ có thai và cho con bú không dùng."},
"a-nguy":{"lv": "luu", "lab": "KIÊNG PHỤ NỮ CÓ THAI", "txt": "Dược điển ghi: phụ nữ có thai cấm dùng. Chỉ dùng 1–1,5 g theo Dược điển, chủ yếu trong hoàn tán hoặc cao dán ngoài; người tỳ vị yếu nên thận trọng."},
"tu-ki-quan-chung":{"lv": "doc", "lab": "ĐỘC NHẸ (小毒) · KHÔNG DÙNG LẪN QUÁN CHÚNG", "txt": "Dược điển ghi tính vị ‘có độc nhẹ’ (小毒); liều 5–9 g/ngày. Không dùng quá liều hoặc kéo dài; phụ nữ có thai thận trọng (theo y văn). Tên ‘quán chúng’ gồm nhiều loài dương xỉ khác nhau (Miên mã quán chúng, Cyrtomium…), cần phân biệt đúng loài trước khi dùng."},
"lang-doc":{"lv": "doc", "lab": "ĐỘC – CHỈ DÙNG NGOÀI", "txt": "Dược điển ghi có độc (有毒), chỉ dùng ngoài, nấu cao đắp. Nhựa mủ kích ứng da và niêm mạc. Không uống, không tự dùng; không dùng chung với Mật đà tăng. Không nhầm với cây ‘lang độc’ họ Trầm (Stellera chamaejasme)."},
"truc-tiet-sam":{"lv": "luu", "lab": "THẬN TRỌNG KHI CÓ THAI", "txt": "Dược điển không ghi cảnh báo riêng. Theo y văn, phụ nữ mang thai và người nhiệt thịnh nên dùng theo thầy thuốc; không nhầm với Nhân sâm, Tam thất hay Sâm Ngọc Linh. Chứng cứ lâm sàng ở người còn hạn chế."},
"chau-tu-sam":{"lv": "luu", "lab": "TÍNH HƠI LẠNH, THẬN TRỌNG", "txt": "Dược điển không ghi cảnh báo riêng. Tính hơi lạnh nên người tỳ vị hư hàn, đại tiện lỏng thận trọng; phụ nữ mang thai dùng theo thầy thuốc (theo y văn). Chỉ dùng đúng liều Dược điển 3–9 g."},
"khai-dang-tu":{"lv": "doc", "lab": "DƯỢC ĐIỂN GHI CÓ ĐỘC NHẸ, KHÔNG DÙNG SỐNG", "txt": "Dược điển ghi tính mát, có độc nhẹ (小毒) và ghi rõ không nên dùng sống; chỉ dùng hạt đã sao chín, bỏ vỏ, nghiền bột, đúng liều 10–15 g. Hạt sống có thể gây buồn nôn, nôn, đau bụng. Không tự ăn hạt tươi hoặc hạt nhặt ngoài rừng."},
"hac-chung-thao-tu":{"lv": "manh", "lab": "CẤM CHO PHỤ NỮ CÓ THAI VÀ BỆNH NHIỆT", "txt": "Dược điển ghi: phụ nữ mang thai và người mắc bệnh nhiệt cấm dùng. Liều 2–6 g, ngoài ra có thể dùng ngoài. Không dùng thay thế bằng sản phẩm ‘black seed’ (loài khác) và dầu hạt mà không hỏi thầy thuốc."},
"chich-cam-thao":{"lv": "luu", "lab": "KHÔNG DÙNG CÙNG HẢI TẢO, ĐẠI KÍCH, CAM TOẠI, NGUYÊN HOA", "txt": "Dược điển ghi không nên dùng cùng Hải tảo, Kinh đại kích, Hồng đại kích, Cam toại, Nguyên hoa. Dùng nhiều hoặc lâu ngày có thể gây giữ nước, phù, tăng huyết áp, hạ kali máu (giả cường aldosteron); người cao huyết áp, suy tim, bệnh thận, thai kỳ cần hỏi thầy thuốc."},
"vu-son-dam-duong-hoac":{"lv": "luu", "lab": "ÂM HƯ HỎA VƯỢNG KHÔNG DÙNG", "txt": "Dược điển không ghi cảnh báo riêng. Theo giáo trình: thuốc cay ấm táo, người âm hư hỏa vượng không nên dùng. Có báo cáo về tổn thương gan với chế phẩm Dâm dương hoắc dùng kéo dài nên cần theo dõi; chứng cứ còn hạn chế. Chỉ dùng đúng liều 3–9 g."},
"nhuy-nhan":{"lv": "luu", "lab": "CHỈ DÙNG THEO CHỈ ĐỊNH", "txt": "Dược điển không ghi cảnh báo riêng. Nhuy nhân là thuốc chữa mắt do phong nhiệt, can huyết hư; không tự nhỏ hoặc rửa mắt bằng nước sắc, cần thầy thuốc hướng dẫn. Theo giáo trình, người tỳ vị hư hàn, tiêu chảy nên thận trọng. Chứng cứ lâm sàng ở người còn hạn chế."},
"duc-thu-thao":{"lv": "doc", "lab": "CÓ ĐỘC NHẸ (有小毒) · LIỀU RẤT THẤP", "txt": "Dược điển ghi tính vị ‘có độc nhẹ’ (有小毒) và liều 1–3 g/ngày, thấp hơn nhiều so với đa số vị thuốc thanh nhiệt khác. Không vượt liều, không dùng kéo dài, chỉ dùng theo toa của thầy thuốc; thận trọng với phụ nữ có thai (theo y văn)."},
"xu-linh-dan-thao":{"lv": "doc", "lab": "ĐỘC (有毒) · KHÔNG TỰ DÙNG", "txt": "Dược điển ghi tính vị ‘có độc’ (有毒), liều 9–15 g/ngày. Không dùng quá liều hoặc kéo dài; thận trọng với phụ nữ có thai, người tỳ vị hư hàn, người có bệnh gan thận (theo y văn). Chỉ dùng theo toa của thầy thuốc."},
"ba-dau-suong":{"lv": "doc", "lab": "ĐỘC MẠNH (大毒) · CẤM KHI CÓ THAI", "txt": "Dược điển ghi tính vị ‘cay, nóng; có độc mạnh’ (有大毒), liều 0,1–0,3 g, nhiều khi dùng trong hoàn tán; phụ nữ có thai cấm dùng, không dùng chung Khiên ngưu tử. Xổ rất dữ dội, kích ứng da và niêm mạc; không tự ý dùng."},
"thien-kim-tu-suong":{"lv": "doc", "lab": "ĐỘC (有毒) · CẤM KHI CÓ THAI", "txt": "Dược điển ghi tính vị ‘cay, ấm; có độc’ (有毒), liều 0,5–1 g, nhiều khi dùng trong hoàn tán; phụ nữ có thai cấm dùng. Xổ mạnh, nhựa và dầu kích ứng da, mắt; không tự ý uống."},
"hat-lanh":{"lv": "luu", "lab": "LƯU Ý · TIÊU CHẢY KHÔNG DÙNG", "txt": "Dược điển ghi người đại tiện lỏng, tiêu chảy cấm dùng. Không ăn hạt sống nhiều và kéo dài (theo y văn hạt chứa chất sinh cyanid lượng nhỏ); không vượt liều 9–15 g/ngày."},
"che-xuyen-o":{"lv": "doc", "lab": "CÓ ĐỘC (有毒) · THẬN TRỌNG KHI CÓ THAI · KỴ BÁN HẠ, QUA LÂU, BỐI MẪU", "txt": "Dược điển ghi tính vị ‘có độc’ (有毒), thận trọng khi có thai, kỵ phối với Bán hạ, Qua lâu, Thiên hoa phấn, các loại Bối mẫu, Bạch liễm, Bạch cập. Liều 1,5–3 g, phải sắc trước và sắc lâu. Alcaloid aconitin có thể gây loạn nhịp tim, tê lan, nôn và ngộ độc nặng nếu chưa bào chế đủ hoặc dùng quá liều; không tự ý dùng."},
"che-thao-o":{"lv": "doc", "lab": "CÓ ĐỘC (有毒) · THẬN TRỌNG KHI CÓ THAI · KỴ BÁN HẠ, QUA LÂU, BỐI MẪU", "txt": "Dược điển ghi tính vị ‘có độc’ (有毒), thận trọng khi có thai, kỵ phối với Bán hạ, Qua lâu, Thiên hoa phấn, các loại Bối mẫu, Bạch liễm, Bạch cập. Liều 1,5–3 g, nên sắc trước và sắc lâu. Có thể gây loạn nhịp tim, tê miệng lưỡi, nôn và ngộ độc nặng nếu dùng quá liều hoặc chế chưa kỹ; không tự ý dùng."},
"dai-ke-than":{"lv": "luu", "lab": "CHẢY MÁU NẶNG CẦN KHÁM", "txt": "Đây là thuốc cầm máu dạng sao than, chỉ hỗ trợ. Nôn ra máu, ho ra máu, đi ngoài phân đen hoặc ra máu số lượng nhiều, rong kinh kéo dài cần đi khám ngay để tìm nguyên nhân, không tự dùng thuốc thay cho cấp cứu. Dùng không quá 5–10 g theo Dược điển."},
"kinh-gioi-than":{"lv": "luu", "lab": "CHẢY MÁU NẶNG CẦN KHÁM", "txt": "Dạng sao than dùng để cầm máu, không dùng thay Kinh giới sống giải biểu. Đi ngoài ra máu, rong kinh, băng huyết sau đẻ có thể là dấu hiệu bệnh nặng, cần đi khám ngay; không tự điều trị. Không vượt 5–10 g theo Dược điển."},
"kinh-gioi-tuy-than":{"lv": "luu", "lab": "CHẢY MÁU NẶNG CẦN KHÁM", "txt": "Dạng sao than của bông Kinh giới dùng để cầm máu. Đi ngoài ra máu, rong kinh, băng huyết hoặc choáng sau đẻ là tình trạng cần cấp cứu, không tự điều trị bằng thuốc nam. Không vượt 5–10 g theo Dược điển."},
"qua-tu-kim":{"lv": "luu", "lab": "ĐỪNG NHẦM VỚI VIỄN CHÍ", "txt": "Dược điển không ghi cảnh báo riêng. Qua tử kim (Polygala japonica, dùng toàn cây) là vị khác Viễn chí (Polygala tenuifolia, dùng rễ), tuy cùng chi và cùng chứa saponin. Theo y văn, saponin có thể kích ứng dạ dày nên người viêm loét dạ dày cần thận trọng."},
"da-ma-truy":{"lv": "luu", "lab": "LIỀU 30–60 G · THẬN TRỌNG VỚI GAN", "txt": "Dược điển không ghi cảnh báo riêng và chỉ nêu liều 30–60 g. Theo y văn, một số loài thuộc chi Eupatorium được báo cáo chứa alkaloid pyrrolizidin có thể hại gan; dữ liệu của loài này còn hạn chế nên không dùng quá liều hoặc kéo dài, người bệnh gan, phụ nữ có thai và cho con bú nên hỏi thầy thuốc."},
"bao-ma-tu-bi":{"lv": "luu", "lab": "ĐỪNG NHẦM VỚI ĐINH HƯƠNG", "txt": "Dược điển không ghi cảnh báo riêng. Bạo mã tử bì (vỏ cây Syringa, họ Ô liu) khác hẳn Đinh hương (nụ hoa Syzygium aromaticum, họ Sim). Theo giáo trình, tính hơi hàn nên người tỳ vị hư hàn, hay lạnh bụng tiêu chảy cần thận trọng."},
"thien-truc-hoang":{"lv": "luu", "lab": "TÍNH HÀN · DỄ NHẦM TRÚC HOÀNG", "txt": "Dược điển không ghi cảnh báo riêng. Theo giáo trình, tính hàn nên người tỳ vị hư hàn, ho đờm trắng loãng không nên dùng. Không nhầm với Trúc hoàng (竹黄, nấm Shiraia bambusicola) hay hàng pha trộn trên thị trường; trẻ em sốt co giật cần đi khám, không tự điều trị tại nhà."},
"phap-ban-ha":{"lv": "luu", "lab": "KHÔNG DÙNG CHUNG Ô ĐẦU, PHỤ TỬ", "txt": "Dược điển ghi: không nên dùng chung với Xuyên ô, Chế xuyên ô, Thảo ô, Chế thảo ô, Phụ tử. Dược điển không đánh dấu có độc cho dạng đã chế này (khác với Bán hạ sống, ghi là có độc), nhưng đừng tự ăn Bán hạ sống và chỉ dùng hàng đã chế đạt chuẩn."},
"khuong-ban-ha":{"lv": "luu", "lab": "KHÔNG DÙNG CHUNG Ô ĐẦU, PHỤ TỬ", "txt": "Dược điển ghi: không nên dùng chung với Xuyên ô, Chế xuyên ô, Thảo ô, Chế thảo ô, Phụ tử. Dược điển không đánh dấu có độc cho dạng đã chế này, nhưng có dùng phèn chua (muối nhôm) và quy định giới hạn phèn; theo y văn người suy thận hoặc dùng kéo dài nên hỏi thầy thuốc."},
"thanh-ban-ha":{"lv": "luu", "lab": "KHÔNG DÙNG CHUNG Ô ĐẦU, PHỤ TỬ", "txt": "Dược điển ghi: không nên dùng chung với Xuyên ô, Chế xuyên ô, Thảo ô, Chế thảo ô, Phụ tử. Dược điển không đánh dấu có độc cho dạng đã chế này, nhưng có dùng phèn chua (muối nhôm) và quy định giới hạn phèn; theo y văn người suy thận hoặc dùng kéo dài nên hỏi thầy thuốc."},
"che-thien-nam-tinh":{"lv": "doc", "lab": "ĐỘC (有毒) · THẬN TRỌNG KHI CÓ THAI", "txt": "Dược điển ghi tính vị ‘có độc’ (有毒) và 孕妇慎用 (thận trọng khi có thai); liều 3–9 g. Củ sống rất độc, gây tê rát lưỡi họng; chỉ dùng loại đã chế đúng quy cách, không tự chế, không nhầm với các cây họ Ráy dại."},
"dam-nam-tinh":{"lv": "luu", "lab": "GỐC NAM TINH · DÙNG MẬT ĐỘNG VẬT", "txt": "Dược điển không ghi có độc hay cảnh báo riêng cho vị này. Nguyên liệu là Thiên nam tinh (loại sống có độc) trộn mật bò, dê hoặc heo; theo y văn phụ nữ có thai, người hư hàn nên hỏi thầy thuốc. Người ăn chay cần biết có thành phần động vật."},
"tri-chu-huong":{"lv": "luu", "lab": "CÓ THỂ GÂY BUỒN NGỦ", "txt": "Dược điển không ghi cảnh báo riêng và chỉ nêu liều 3–6 g. Theo y văn về chi Valeriana, có thể gây buồn ngủ nên tránh khi lái xe, vận hành máy; không dùng cùng thuốc an thần mạnh khi chưa hỏi thầy thuốc. Phụ nữ có thai, cho con bú nên tránh khi chưa có chỉ định."},
"ngai-phien":{"lv": "luu", "lab": "THẬN TRỌNG Ở PHỤ NỮ CÓ THAI", "txt": "Dược điển ghi: phụ nữ có thai dùng thận trọng (孕妇慎用). Thuốc khai khiếu tính tán, chỉ dùng trong hoàn tán với lượng rất nhỏ (0,15–0,3 g). Theo y văn, uống nhiều hoặc dùng ngoài trên diện da tổn thương rộng có thể gây kích ứng; trẻ nhỏ, người hư nhược cần hỏi thầy thuốc. Không nhầm với Ngải diệp (lá Ngải cứu) hoặc long não (camphor)."},
"thien-nhien-bang-phien":{"lv": "luu", "lab": "THẬN TRỌNG Ở PHỤ NỮ CÓ THAI", "txt": "Dược điển ghi: phụ nữ có thai dùng thận trọng (孕妇慎用). Thuốc khai khiếu tính tán, chỉ dùng trong hoàn tán với lượng nhỏ (0,3–0,9 g). Không nhầm với long não (camphor, 樟脑) vốn độc khi uống, và không tự cất lá cây Long não để thay thế. Theo y văn, dùng ngoài trên vùng da tổn thương rộng có thể gây kích ứng."},
"ma-tien-tu-phan":{"lv": "doc", "lab": "ĐỘC MẠNH (大毒)", "txt": "Dược điển ghi có độc mạnh (大毒). Chứa strychnin gây co giật toàn thân, nguy cơ liệt hô hấp; liều dùng chỉ 0,3–0,6 g, vào hoàn tán, do thầy thuốc kê. Phụ nữ có thai cấm dùng; không dùng nhiều hoặc kéo dài; vận động viên thận trọng; độc tố ngấm qua da nên không bôi diện rộng. Không tự dùng."},
"thao-o-diep":{"lv": "doc", "lab": "ĐỘC NHẸ (小毒)", "txt": "Dược điển ghi có độc nhẹ (小毒). Lá của loài Ô đầu chứa alcaloid họ Aconitum có thể độc tim và thần kinh; chỉ dùng 1–1,2 g vào hoàn tán theo chỉ định của thầy thuốc. Phụ nữ có thai thận trọng. Không tự hái dùng, không nhầm với rễ củ Thảo ô độc mạnh."},
"vu-chau-lau-lo":{"lv": "luu", "lab": "THẬN TRỌNG KHI CÓ THAI", "txt": "Dược điển ghi 【注意】孕妇慎用 (thận trọng khi có thai) và không gắn nhãn độc cho vị này (性味与归经: 苦，寒。归胃经). Theo y văn người tỳ vị hư hàn thận trọng; chỉ dùng đúng loài (Echinops latifolius hoặc E. grijsii), không nhầm với Lậu lô (祁州漏芦) hay các vị khác."},
"xuyen-xa-can":{"lv": "luu", "lab": "VỊ ĐẮNG HÀN; ĐỪNG NHẦM XẠ CAN", "txt": "Dược điển không ghi cảnh báo riêng. Theo y văn: thận trọng với người tỳ vị hư hàn, đại tiện lỏng và phụ nữ có thai. Không nhầm với Xạ can (Belamcanda chinensis)."},
"chu-sa-can":{"lv": "luu", "lab": "ĐỪNG NHẦM VỚI CHU SA (THỦY NGÂN)", "txt": "Dược điển không ghi cảnh báo riêng. Chu sa căn là rễ cây, hoàn toàn khác Chu sa (khoáng vật chứa thủy ngân, có độc). Theo y văn: phụ nữ có thai nên thận trọng."},
"kho-huyen-sam":{"lv": "luu", "lab": "RẤT ĐẮNG HÀN, KHÔNG DÙNG DÀI NGÀY", "txt": "Dược điển không ghi cảnh báo riêng. Theo y văn: người tỳ vị hư hàn, đại tiện lỏng và phụ nữ có thai nên thận trọng; thực nghiệm ghi nhận cucurbitacin có độc tính tế bào ở liều cao."},
"tieu-chi-tu":{"lv": "luu", "lab": "VỊ ĐẮNG HÀN, THẬN TRỌNG TỲ VỊ HƯ", "txt": "Dược điển không ghi mục chú ý. Theo y văn: người tỳ vị hư hàn, đại tiện lỏng nên thận trọng; không dùng quá 6–9 g/ngày."},
"tieu-diep-lien":{"lv": "doc", "lab": "ĐỘC NHẸ – PHÁ HUYẾT", "txt": "Dược điển ghi ‘có độc nhẹ’. Quả thuộc nhóm lignan loại podophyllotoxin có hoạt tính độc tế bào. Không tự dùng, nhất là phụ nữ có thai; chỉ dùng theo chỉ định thầy thuốc, không vượt liều Dược điển (3–9 g/ngày)."},
"dien-ke-huyet-dang":{"lv": "luu", "lab": "HOẠT HUYẾT – THẬN TRỌNG KHI CÓ THAI", "txt": "Vị hoạt huyết điều kinh; phụ nữ có thai, kinh ra nhiều hoặc đang chảy máu nên hỏi thầy thuốc. Dễ nhầm với Kê huyết đằng (Spatholobus) vì cùng tên gọi tắt."},
"dai-diep-tu-chau":{"lv": "luu", "lab": "CHẢY MÁU NẶNG LÀ CẤP CỨU", "txt": "Chảy máu ồ ạt, ho ra máu hoặc nôn ra máu cần đi cấp cứu, không tự điều trị bằng thảo dược. Vị thuốc có tính tán ứ nên phụ nữ có thai cần hỏi thầy thuốc."},
"tieu-tan-lang":{"lv": "luu", "lab": "CHẾ PHẨM CỦA TÂN LANG, CHỨA ARECOLINE", "txt": "Dược điển không ghi cảnh báo riêng. Theo y văn, hoạt chất arecoline có thể gây chảy nước dãi, buồn nôn, nhịp tim chậm, co thắt phế quản ở người nhạy cảm; thận trọng ở người hen, tim chậm, người có thai. Nhai cau lâu dài liên quan ung thư khoang miệng. Không dùng liều cao tẩy sán khi chưa có chỉ định của thầy thuốc; liều Dược điển 3–10 g."},
"dai-toan":{"lv": "luu", "lab": "KÍCH ỨNG DA, DẠ DÀY", "txt": "Tỏi sống đắp trực tiếp lên da có thể gây phồng rộp, bỏng; ăn nhiều hoặc lúc đói dễ kích ứng dạ dày. Người đang dùng thuốc chống đông cần hỏi thầy thuốc. Dược điển không ghi mục chú ý cho vị này."},
"phuong-vi-thao":{"lv": "luu", "lab": "TÍNH LẠNH – NHẦM LOÀI DƯƠNG XỈ", "txt": "Vị thuốc tính lạnh, người đi lỏng, bụng lạnh nên hỏi thầy thuốc. Dương xỉ có nhiều loài giống nhau, một số loài Pteris tích tụ arsen từ đất; không tự hái ở bãi đất ô nhiễm hoặc cạnh đường lớn."},
"long-quy":{"lv": "doc", "lab": "ĐỘC NHẸ – QUẢ XANH, LÁ GIÀ", "txt": "Toàn cây, nhất là quả xanh và lá già, chứa glycoalkaloid (solanin); ăn hoặc dùng quá liều có thể gây buồn nôn, đau bụng, chóng mặt. Không cho trẻ em, phụ nữ có thai dùng; chỉ dùng theo chỉ định thầy thuốc. Không hái ăn khi chưa phân biệt rõ với các loài Solanum khác."},
"xa-moi":{"lv": "luu", "lab": "ÍT ĐỘC – KHÔNG DÙNG LIỀU CAO", "txt": "Một số tài liệu ghi vị này có độc nhẹ; chỉ dùng liều thường, không kéo dài, không dùng cho phụ nữ có thai. Dùng ngoài trên vết thương hở nên hỏi thầy thuốc."},
"bach-anh":{"lv": "doc", "lab": "ĐỘC NHẸ – HỌ CÀ", "txt": "Toàn cây chứa alkaloid steroid; dùng quá liều hoặc kéo dài có thể gây buồn nôn, đau bụng, chóng mặt. Không cho trẻ em, phụ nữ có thai dùng; không ăn quả. Chỉ dùng theo chỉ định thầy thuốc, không tự dùng chống u."},
"xu-mau-don":{"lv": "luu", "lab": "THẬN TRỌNG KHI CÓ THAI", "txt": "Theo giáo trình, phụ nữ có thai nên hỏi thầy thuốc trước khi dùng; không dùng kéo dài, không nhầm với Mẫu đơn bì."},
"khe-hoang-thao":{"lv": "luu", "lab": "ĐẮNG LẠNH – NHẦM LOÀI", "txt": "Vị đắng lạnh, người tiêu chảy do lạnh bụng, tỳ vị hư hàn không nên dùng. Nhiều loài Isodon cùng được gọi là Khê hoàng thảo; vàng da cần khám và điều trị y khoa, không tự dùng thay thuốc."},
"toan-tuong-thao":{"lv": "luu", "lab": "OXALAT – THẬN TRỌNG BỆNH THẬN", "txt": "Chứa nhiều oxalat; người có sỏi thận, bệnh thận, gút không nên dùng nhiều hoặc kéo dài. Phụ nữ có thai nên hỏi thầy thuốc."},
"thiet-hien-thai":{"lv": "luu", "lab": "NHẦM LOÀI HỌ THẦU DẦU", "txt": "Họ Thầu dầu có nhiều loài có độc hoặc kích ứng; chỉ dùng đúng loài Acalypha australis do thầy thuốc hướng dẫn. Phụ nữ có thai và người tỳ vị hư hàn nên thận trọng."},
"kho-qua":{"lv": "luu", "lab": "HẠ ĐƯỜNG HUYẾT – KHÔNG ĂN HẠT", "txt": "Có thể làm giảm đường huyết, cần theo dõi nếu đang dùng thuốc đái tháo đường; phụ nữ có thai không dùng liều thuốc và không ăn hạt. Người thiếu men G6PD nên tránh hạt. Không nhầm với Mộc miết tử (hạt gấc) có độc."}
};
